svg.script:
(function () {
'use strict';
// ================================================================ core helpers
const NS = 'http://www.w3.org/2000/svg';
const INK = '#15121c', PAPER = '#fff3d6', RED = '#e8232f', YEL = '#ffd23f', CYAN = '#22c7f0',
  MAG = '#ff3d9a', ORG = '#ff8a1f', GRN = '#37c95b', PUR = '#7b3fe4', WHT = '#ffffff';
const TAU = Math.PI * 2, PI = Math.PI;
const FW = 560, FH = 720;
const app = document.getElementById('app');
const defs = document.querySelector('defs');

const rnd = (a, b) => a + Math.random() * (b - a);
const rndi = (a, b) => Math.floor(a + Math.random() * (b - a + 1));
const pick = a => a[Math.floor(Math.random() * a.length)];
const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
const lerp = (a, b, t) => a + (b - a) * t;
const f1 = v => Math.round(v * 10) / 10;
const easeOut = t => 1 - (1 - t) * (1 - t);
const easeIn = t => t * t;
const easeBack = t => { const c = 1.7; return 1 + (c + 1) * Math.pow(t - 1, 3) + c * Math.pow(t - 1, 2); };

function el(tag, a, parent) {
  const n = document.createElementNS(NS, tag);
  if (a) for (const k in a) n.setAttribute(k, a[k]);
  if (parent) parent.appendChild(n);
  return n;
}
function sa(n, a) { for (const k in a) n.setAttribute(k, a[k]); return n; }
function inkA(a, sw) { a.stroke = INK; a['stroke-width'] = sw; a['stroke-linejoin'] = 'round'; a['stroke-linecap'] = 'round'; return a; }
function P(g, d, fill, sw, ex) { const a = { d, fill: fill || 'none' }; if (sw) inkA(a, sw); if (ex) Object.assign(a, ex); return el('path', a, g); }
function C(g, cx, cy, r, fill, sw, ex) { const a = { cx, cy, r, fill: fill || 'none' }; if (sw) inkA(a, sw); if (ex) Object.assign(a, ex); return el('circle', a, g); }
function E(g, cx, cy, rx, ry, fill, sw, ex) { const a = { cx, cy, rx, ry, fill: fill || 'none' }; if (sw) inkA(a, sw); if (ex) Object.assign(a, ex); return el('ellipse', a, g); }
function R(g, x, y, w, h, fill, sw, ex) { const a = { x, y, width: w, height: h, fill: fill || 'none' }; if (sw) inkA(a, sw); if (ex) Object.assign(a, ex); return el('rect', a, g); }
function grp(parent, tf) { return el('g', tf ? { transform: tf } : null, parent); }
function T(g, x, y, s, size, fill, o) {
  o = o || {};
  const a = { x, y, 'font-size': size, fill: fill || INK, 'font-weight': o.w || 900 };
  if (o.anchor) a['text-anchor'] = o.anchor;
  if (o.ol) { a.stroke = o.olc || INK; a['stroke-width'] = o.ol; a['stroke-linejoin'] = 'round'; a['paint-order'] = 'stroke'; }
  if (o.ex) Object.assign(a, o.ex);
  const t = el('text', a, g);
  t.textContent = s;
  return t;
}
function show(n, v) { if (n) n.style.display = v ? '' : 'none'; }
function starD(n, r1, r2, jit) {
  let d = '';
  for (let i = 0; i < n * 2; i++) {
    const a = (i / (n * 2)) * TAU - PI / 2;
    const r = (i % 2 ? r2 : r1) * (1 + (jit ? rnd(-jit, jit) : 0));
    d += (i ? 'L' : 'M') + f1(Math.cos(a) * r) + ' ' + f1(Math.sin(a) * r);
  }
  return d + 'Z';
}
function circD(x, y, r) {
  return 'M' + f1(x - r) + ' ' + f1(y) + 'a' + r + ' ' + r + ' 0 1 0 ' + (2 * r) + ' 0a' + r + ' ' + r + ' 0 1 0 ' + (-2 * r) + ' 0';
}
function cloudD(cx, cy, rx, ry, n) {
  const pts = [];
  for (let i = 0; i < n; i++) { const a = (i / n) * TAU; pts.push([cx + Math.cos(a) * rx, cy + Math.sin(a) * ry]); }
  const r = f1(((rx + ry) / n) * 1.3);
  let d = 'M' + f1(pts[0][0]) + ' ' + f1(pts[0][1]);
  for (let i = 1; i <= n; i++) { const p = pts[i % n]; d += 'A' + r + ' ' + r + ' 0 0 1 ' + f1(p[0]) + ' ' + f1(p[1]); }
  return d + 'Z';
}
function raysD(n, r, skip) {
  let d = '';
  for (let i = 0; i < n; i += skip || 2) {
    const a0 = (i / n) * TAU, a1 = ((i + 1) / n) * TAU;
    d += 'M0 0L' + f1(Math.cos(a0) * r) + ' ' + f1(Math.sin(a0) * r) + 'L' + f1(Math.cos(a1) * r) + ' ' + f1(Math.sin(a1) * r) + 'Z';
  }
  return d;
}
function speedLinesD(cx, cy, n, r0, r1) {
  let d = '';
  for (let i = 0; i < n; i++) {
    const a = rnd(0, TAU), w = rnd(0.006, 0.02), ra = r0 * rnd(0.8, 1.3);
    d += 'M' + f1(cx + Math.cos(a - w) * r1) + ' ' + f1(cy + Math.sin(a - w) * r1) + 'L' + f1(cx + Math.cos(a) * ra) + ' ' + f1(cy + Math.sin(a) * ra) + 'L' + f1(cx + Math.cos(a + w) * r1) + ' ' + f1(cy + Math.sin(a + w) * r1) + 'Z';
  }
  return d;
}
function splitLines(s, n) {
  if (s.length <= n) return [s];
  const mid = Math.ceil(s.length / 2);
  let best = -1;
  for (let i = 1; i < s.length; i++) if ('，。！？、·：；…'.indexOf(s[i - 1]) >= 0 && Math.abs(i - mid) <= 4 && i <= n) best = i;
  const k = best > 0 ? best : Math.min(n, mid);
  return [s.slice(0, k), s.slice(k)];
}

// ================================================================ comic lettering (stroke font)
const FONT_SRC = {
  A: '0,6 1.5,0 2.5,0 4,6|0.8,3.9 3.2,3.9',
  B: '0,3 0,0 2.8,0 3.8,0.9 3.8,2.1 2.8,3 0,3 0,6 3,6 4,5 4,4 3,3',
  C: '4,1 3,0 1,0 0,1 0,5 1,6 3,6 4,5',
  D: '0,0 0,6 2.4,6 4,4.4 4,1.6 2.4,0 0,0',
  E: '4,0 0,0 0,6 4,6|0,3 3,3',
  F: '4,0 0,0 0,6|0,3 3,3',
  G: '4,1 3,0 1,0 0,1 0,5 1,6 3,6 4,5 4,3.3 2.2,3.3',
  H: '0,0 0,6|4,0 4,6|0,3 4,3',
  I: '1,0 3,0|2,0 2,6|1,6 3,6',
  J: '1.5,0 4,0 4,5 3,6 1,6 0,5',
  K: '0,0 0,6|4,0 0.2,3.6|1.4,2.7 4,6',
  L: '0,0 0,6 4,6',
  M: '0,6 0,0 2,3 4,0 4,6',
  N: '0,6 0,0 4,6 4,0',
  O: '1,0 3,0 4,1 4,5 3,6 1,6 0,5 0,1 1,0',
  P: '0,6 0,0 3,0 4,1 4,2 3,3 0,3',
  Q: '1,0 3,0 4,1 4,5 3,6 1,6 0,5 0,1 1,0|2.4,4.4 4,6',
  R: '0,6 0,0 3,0 4,1 4,2 3,3 0,3|2,3 4,6',
  S: '4,1 3,0 1,0 0,1 0,2 1,3 3,3 4,4 4,5 3,6 1,6 0,5',
  T: '0,0 4,0|2,0 2,6',
  U: '0,0 0,5 1,6 3,6 4,5 4,0',
  V: '0,0 2,6 4,0',
  W: '0,0 0.9,6 2,2.6 3.1,6 4,0',
  X: '0,0 4,6|4,0 0,6',
  Y: '0,0 2,3 4,0|2,3 2,6',
  Z: '0,0 4,0 0,6 4,6',
  0: '1,0 3,0 4,1 4,5 3,6 1,6 0,5 0,1 1,0',
  1: '0.8,1.2 2,0 2,6|0.8,6 3.2,6',
  2: '0,1 1,0 3,0 4,1 4,2.2 0,6 4,6',
  3: '0,0.8 1,0 3,0 4,1 4,2 3,3 1.5,3|3,3 4,4 4,5 3,6 1,6 0,5.2',
  4: '3,6 3,0 0,4 4,4',
  5: '4,0 0.4,0 0.1,2.9 3,2.8 4,3.8 4,5 3,6 1,6 0,5.2',
  6: '3.8,0.6 3,0 1,0 0,1 0,5 1,6 3,6 4,5 4,3.8 3,2.8 1,2.8 0,3.8',
  7: '0,0 4,0 1.6,6',
  8: '1,3 0,2 0,1 1,0 3,0 4,1 4,2 3,3 1,3 0,4 0,5 1,6 3,6 4,5 4,4 3,3',
  9: '4,2.2 3,3.2 1,3.2 0,2.2 0,1 1,0 3,0 4,1 4,5 3,6 1,6 0.2,5.4',
  '!': '2,0 2,4|2,5.8 2,6',
  '?': '0,1 1,0 3,0 4,1 4,2 2,3.4 2,4.1|2,5.8 2,6',
  '-': '0.6,3 3.4,3',
  '.': '2,5.8 2,6',
  "'": '2,0 2,1.6',
  ':': '2,1.6 2,1.8|2,4.6 2,4.8',
  '/': '0.6,6 3.4,0',
  '+': '2,1.4 2,4.6|0.4,3 3.6,3',
  '%': '0,6 4,0|0.6,0.6 0.8,0.6|3.2,5.4 3.4,5.4',
  '*': '2,1 2,5|0.3,2 3.7,4|0.3,4 3.7,2'
};
const FONT = {};
for (const k in FONT_SRC) FONT[k] = FONT_SRC[k].split('|').map(s => s.trim().split(/\s+/).map(p => p.split(',').map(Number)));
const NARROW = "!.:'";
function glyphD(str, size, ox, oy, sp) {
  const u = size / 6;
  if (sp == null) sp = 1.5;
  let x = 0, d = '';
  for (const ch of str) {
    if (ch === ' ') { x += 3 * u; continue; }
    const g = FONT[ch] || FONT[ch.toUpperCase()];
    const nar = NARROW.indexOf(ch) >= 0;
    if (g) for (const pl of g) for (let i = 0; i < pl.length; i++) {
      d += (i ? 'L' : 'M') + f1(ox + x + (pl[i][0] - (nar ? 1 : 0)) * u) + ' ' + f1(oy + (pl[i][1] - 6) * u);
    }
    x += ((nar ? 2 : 4) + sp) * u;
  }
  return { d, w: Math.max(0, x - sp * u) };
}
function comic(parent, str, o) {
  o = o || {};
  const g = el('g', null, parent);
  const back = el('path', { fill: 'none', stroke: o.ink || INK, 'stroke-linecap': 'round', 'stroke-linejoin': 'round' }, g);
  const front = el('path', { fill: 'none', stroke: o.fill || YEL, 'stroke-linecap': 'round', 'stroke-linejoin': 'round' }, g);
  const size = o.size || 32, u = size / 6;
  const wt = (o.weight || 1.35) * u, ol = (o.outline == null ? 0.85 : o.outline) * u, sh = (o.shadow == null ? 0.7 : o.shadow) * u;
  back.setAttribute('stroke-width', f1(wt + ol * 2));
  front.setAttribute('stroke-width', f1(wt));
  const obj = { g, back, front, w: 0, str: null };
  obj.set = s => {
    s = String(s);
    if (s === obj.str) return obj;
    obj.str = s;
    const m = glyphD(s, size, 0, 0, o.sp);
    const ax = o.anchor === 'start' ? 0 : o.anchor === 'end' ? -m.w : -m.w / 2;
    const main = glyphD(s, size, ax, 0, o.sp).d;
    back.setAttribute('d', (sh ? glyphD(s, size, ax + sh, sh, o.sp).d : '') + main);
    front.setAttribute('d', main);
    obj.w = m.w;
    return obj;
  };
  obj.set(str);
  let tf = 'translate(' + (o.x || 0) + ' ' + (o.y || 0) + ')';
  if (o.rot) tf += ' rotate(' + o.rot + ')';
  if (o.skew) tf += ' skewX(' + o.skew + ')';
  g.setAttribute('transform', tf);
  return obj;
}

// ================================================================ audio (Web Audio synthesis)
const AU = {
  ctx: null, master: null, sfxBus: null, musBus: null, noiseBuf: null, muted: false, last: {},
  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return; }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      const c = new AC();
      this.ctx = c;
      const comp = c.createDynamicsCompressor();
      comp.threshold.value = -14; comp.knee.value = 10; comp.ratio.value = 5;
      comp.connect(c.destination);
      this.master = c.createGain(); this.master.gain.value = this.muted ? 0 : 0.6; this.master.connect(comp);
      this.sfxBus = c.createGain(); this.sfxBus.gain.value = 0.85; this.sfxBus.connect(this.master);
      this.musBus = c.createGain(); this.musBus.gain.value = 0.34; this.musBus.connect(this.master);
      const n = c.sampleRate, b = c.createBuffer(1, n, n), d = b.getChannelData(0);
      for (let i = 0; i < n; i++) d[i] = Math.random() * 2 - 1;
      this.noiseBuf = b;
      MUS.start();
    } catch (e) { this.ctx = null; }
  },
  setMute(m) {
    this.muted = m;
    if (this.master) this.master.gain.setTargetAtTime(m ? 0 : 0.6, this.ctx.currentTime, 0.02);
  },
  ok(key, gap) {
    if (!this.ctx || this.muted) return false;
    if (!key) return true;
    const now = this.ctx.currentTime;
    if (this.last[key] && now - this.last[key] < gap) return false;
    this.last[key] = now;
    return true;
  },
  tone(f, dur, type, vol, f2, when, bus) {
    const c = this.ctx; if (!c) return;
    const t = c.currentTime + (when || 0);
    const o = c.createOscillator(), g = c.createGain();
    o.type = type || 'square';
    o.frequency.setValueAtTime(f, t);
    if (f2) o.frequency.exponentialRampToValueAtTime(Math.max(20, f2), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol || 0.1, t + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(bus || this.sfxBus);
    o.start(t); o.stop(t + dur + 0.03);
  },
  noiseAt(t, dur, vol, fa, fb, type, q, bus) {
    const c = this.ctx; if (!c || !this.noiseBuf) return;
    const s = c.createBufferSource(); s.buffer = this.noiseBuf;
    const fl = c.createBiquadFilter(); fl.type = type || 'lowpass'; fl.Q.value = q || 0.8;
    fl.frequency.setValueAtTime(fa, t);
    if (fb && fb !== fa) fl.frequency.exponentialRampToValueAtTime(Math.max(30, fb), t + dur);
    const g = c.createGain();
    g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    s.connect(fl); fl.connect(g); g.connect(bus || this.sfxBus);
    s.start(t, Math.random() * 0.5); s.stop(t + dur + 0.03);
  },
  noise(dur, vol, fa, fb, when, type, q) { if (this.ctx) this.noiseAt(this.ctx.currentTime + (when || 0), dur, vol, fa, fb, type, q); },
  play(name) { const fn = SFX[name]; if (fn && this.ctx && !this.muted) { try { fn(); } catch (e) { /* audio is best-effort */ } } }
};
const SFX = {
  shot() { if (AU.ok('shot', 0.075)) AU.tone(1500, 0.045, 'square', 0.028, 700); },
  laser() { if (AU.ok('laser', 0.11)) AU.tone(190 + Math.random() * 30, 0.1, 'sawtooth', 0.032, 150); },
  hit() { if (AU.ok('hit', 0.05)) AU.tone(420, 0.035, 'square', 0.03, 260); },
  pop() { if (AU.ok('pop', 0.04)) { AU.noise(0.22, 0.3, 3500, 300); AU.tone(220, 0.16, 'triangle', 0.2, 60); } },
  boom() { if (AU.ok('boom', 0.06)) { AU.noise(0.55, 0.5, 2600, 90); AU.tone(110, 0.45, 'sine', 0.42, 32); } },
  huge() { AU.noise(1.6, 0.7, 3000, 50); AU.tone(70, 1.4, 'sine', 0.7, 22); AU.tone(140, 0.8, 'sawtooth', 0.16, 30); },
  item() { if (AU.ok('item', 0.05)) [880, 1175, 1568].forEach((f, i) => AU.tone(f, 0.09, 'square', 0.07, 0, i * 0.06)); },
  power() { [523, 659, 784, 1047, 1319].forEach((f, i) => AU.tone(f, 0.1, 'square', 0.08, 0, i * 0.055)); },
  graze() { if (AU.ok('graze', 0.045)) AU.tone(2600 + Math.random() * 600, 0.03, 'triangle', 0.045, 3800); },
  bomb() { AU.noise(1.8, 0.75, 1800, 50); AU.tone(55, 1.5, 'sine', 0.75, 20); AU.tone(220, 0.6, 'sawtooth', 0.2, 30); },
  die() { AU.tone(700, 0.7, 'sawtooth', 0.26, 50); AU.noise(0.9, 0.6, 2400, 60); },
  shield() { AU.tone(1600, 0.2, 'square', 0.11, 400); AU.tone(1000, 0.3, 'triangle', 0.14, 250, 0.03); },
  ready() { [784, 988, 1175, 1568].forEach((f, i) => AU.tone(f, 0.12, 'triangle', 0.1, 0, i * 0.07)); },
  special() { AU.tone(160, 1.2, 'sawtooth', 0.26, 1800); AU.noise(2.6, 0.35, 300, 5000, 0, 'bandpass', 2); AU.tone(80, 2.4, 'square', 0.1, 60, 0.4); },
  warn() { for (let i = 0; i < 4; i++) { AU.tone(660, 0.36, 'square', 0.12, 880, i * 0.8); AU.tone(880, 0.36, 'square', 0.12, 660, i * 0.8 + 0.4); } },
  move() { if (AU.ok('move', 0.03)) AU.tone(990, 0.05, 'square', 0.06); },
  select() { AU.tone(660, 0.07, 'square', 0.08); AU.tone(1320, 0.12, 'square', 0.08, 0, 0.07); },
  back() { AU.tone(440, 0.1, 'square', 0.07, 220); },
  ding() { if (AU.ok('ding', 0.08)) AU.tone(1760, 0.18, 'triangle', 0.1); },
  phase() { AU.tone(300, 0.5, 'sawtooth', 0.2, 900); AU.noise(0.5, 0.3, 800, 4000, 0, 'bandpass', 1.5); }
};

// ================================================================ music (step sequencer)
const mtof = m => 440 * Math.pow(2, (m - 69) / 12);
function notes(s) {
  return s.trim().split(/\s+/).map(tk => {
    const m = /^([A-G])([#b]?)(\d)$/.exec(tk);
    if (!m) return 0;
    return { C: 0, D: 2, E: 4, F: 5, G: 7, A: 9, B: 11 }[m[1]] + (m[2] === '#' ? 1 : m[2] === 'b' ? -1 : 0) + (parseInt(m[3], 10) + 1) * 12;
  });
}
const DRUMS = {
  none: { k: '................', s: '................', h: '................' },
  rock: { k: 'x.......x.x.....', s: '....x.......x...', h: 'x.x.x.x.x.x.x.x.' },
  drive: { k: 'x...x...x...x...', s: '....x.......x..x', h: 'x.xxx.xxx.xxx.xx' },
  space: { k: 'x.........x.....', s: '........x.......', h: '..x...x...x...x.' },
  boss: { k: 'x..xx..xx..xx..x', s: '....x.......x.x.', h: 'xxxxxxxxxxxxxxxx' },
  fill: { k: 'x...x...x...x...', s: '..........x.xxxx', h: 'x.x.x.x.x.x.x.x.' }
};
const TRACKS = {
  title: { bpm: 124, drum: 'rock', arp: 1, bass: 'x.x.x.xox.x.x.xo', prog: [[48, 'M'], [43, 'M'], [45, 'm'], [41, 'M']],
    lead: notes('G4 . C5 . E5 . G5 . . . E5 . D5 . C5 . D5 . . . B4 . D5 . G5 . . . F5 . E5 D5 E5 . . . C5 . E5 . A5 . G5 . E5 . C5 . F5 . E5 . D5 . C5 . D5 . . . . . . .') },
  s1: { bpm: 150, drum: 'drive', arp: 1, bass: 'x.xox.xox.xox.xo', prog: [[40, 'm'], [48, 'M'], [43, 'M'], [50, 'M']],
    lead: notes('E4 . G4 . B4 . E5 . D5 . B4 . G4 . A4 B4 C5 . . . B4 . A4 . G4 . A4 . B4 . . . B4 . D5 . G5 . F#5 . G5 . D5 . B4 . D5 E5 F#5 . . . E5 . D5 . A4 . D5 . E5 . F#5 .') },
  s2: { bpm: 132, drum: 'space', arp: 1, bass: 'x.......x...x.o.', prog: [[50, 'm'], [46, 'M'], [48, 'M'], [45, 'M']],
    lead: notes('D5 . . . A4 . . . F5 . E5 . D5 . . . Bb4 . . . D5 . F5 . Bb5 . . . A5 . F5 . G5 . . . E5 . C5 . G5 . A5 . G5 . E5 . C#5 . E5 . A5 . . . G5 . F5 . E5 . C#5 .') },
  s3: { bpm: 156, drum: 'drive', arp: 1, bass: 'x.xxx.xox.xxx.xo', prog: [[48, 'm'], [44, 'M'], [46, 'M'], [43, 'M']],
    lead: notes('C5 . Eb5 . G5 . Eb5 . C6 . Bb5 . G5 . Eb5 . Ab5 . . . G5 . F5 . Eb5 . F5 . G5 . . . Bb5 . G5 . F5 . D5 . F5 . G5 . Bb5 . D6 . B5 . . . G5 . . . D5 . F5 . G5 . B5 .') },
  boss: { bpm: 170, drum: 'boss', arp: 1, bass: 'x.xxx.xxx.xxx.xo', prog: [[45, 'm'], [46, 'M'], [43, 'm'], [45, 'M']],
    lead: notes('A4 . G#4 A4 . E4 . A4 . C5 . B4 A4 . E4 . Bb4 . A4 Bb4 . F4 . Bb4 . D5 . C5 Bb4 . F4 . G4 . Bb4 . D5 . Bb4 . G4 . D4 . F4 . G4 . A4 . . . E4 . . . C#5 . E5 . A5 . C#5 .') },
  win: { bpm: 140, drum: 'fill', arp: 1, once: 1, len: 32, bass: 'x...x...x...x...', prog: [[48, 'M'], [43, 'M']],
    lead: notes('C5 . E5 . G5 . C6 . . . G5 . C6 . . . D6 . . . B5 . G5 . C6 . . . . . . .') },
  over: { bpm: 92, drum: 'none', once: 1, len: 32, bass: 'x.......x.......', prog: [[45, 'm'], [40, 'M']],
    lead: notes('A4 . . G4 . . F4 . . E4 . . . . . . D4 . . C4 . . B3 . . . . . . . . .') },
  end: { bpm: 118, drum: 'rock', arp: 1, bass: 'x.x.x.x.x.x.x.x.', prog: [[48, 'M'], [45, 'm'], [41, 'M'], [43, 'M']],
    lead: notes('E5 . D5 . C5 . G4 . C5 . E5 . G5 . . . A5 . G5 . E5 . C5 . E5 . . . . . F5 . E5 . D5 . C5 . A4 . C5 . F5 . . . G5 . . . F5 . E5 . D5 . . . . . . .') }
};
const MUS = {
  tr: null, name: '', step: 0, t: 0, timer: 0,
  start() { if (!this.timer) this.timer = setInterval(() => this.tick(), 30); },
  play(name) { if (this.name === name) return; this.name = name; this.tr = TRACKS[name] || null; this.step = 0; this.t = 0; },
  stop() { this.name = ''; this.tr = null; },
  tick() {
    const c = AU.ctx;
    if (!c || !this.tr || G.mode === 'pause' || (G.mode === 'help' && G.helpFrom === 'pause')) return;
    const tr = this.tr, sd = 60 / tr.bpm / 4;
    if (this.t < c.currentTime) this.t = c.currentTime + 0.04;
    let guard = 0;
    while (this.t < c.currentTime + 0.14 && guard++ < 8) {
      try { this.stepPlay(tr, this.step, this.t, sd); } catch (e) { /* ignore */ }
      this.t += sd; this.step++;
      if (tr.once && this.step >= tr.len) { this.tr = null; this.name = ''; break; }
    }
  },
  stepPlay(tr, step, t, sd) {
    const s = step % 16, bar = Math.floor(step / 16) % tr.prog.length;
    const root = tr.prog[bar][0], ch = tr.prog[bar][1] === 'm' ? [0, 3, 7, 12] : [0, 4, 7, 12];
    const bp = tr.bass[s];
    if (bp !== '.') this.voice(mtof(root + (bp === 'o' ? 12 : 0)), sd * 1.7, 'sawtooth', 0.15, t, 820);
    if (tr.arp && s % 2 === 0) this.voice(mtof(root + 24 + ch[(s >> 1) % 4]), sd * 1.3, 'triangle', 0.05, t, 0);
    const n = tr.lead[step % tr.lead.length];
    if (n) this.voice(mtof(n), sd * 1.9, 'square', 0.065, t, 2600);
    const dr = DRUMS[tr.drum || 'none'];
    if (dr.k[s] === 'x') this.kick(t);
    if (dr.s[s] === 'x') this.snare(t);
    if (dr.h[s] === 'x') AU.noiseAt(t, 0.035, 0.05, 8000, 8000, 'highpass', 0.7, AU.musBus);
  },
  voice(f, dur, type, vol, t, cut) {
    const c = AU.ctx, o = c.createOscillator(), g = c.createGain();
    o.type = type; o.frequency.setValueAtTime(f, t);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    if (cut) { const fl = c.createBiquadFilter(); fl.type = 'lowpass'; fl.frequency.value = cut; o.connect(fl); fl.connect(g); } else o.connect(g);
    g.connect(AU.musBus); o.start(t); o.stop(t + dur + 0.03);
  },
  kick(t) {
    const c = AU.ctx, o = c.createOscillator(), g = c.createGain();
    o.type = 'sine'; o.frequency.setValueAtTime(150, t); o.frequency.exponentialRampToValueAtTime(42, t + 0.12);
    g.gain.setValueAtTime(0.5, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.16);
    o.connect(g); g.connect(AU.musBus); o.start(t); o.stop(t + 0.2);
  },
  snare(t) {
    AU.noiseAt(t, 0.13, 0.2, 1900, 1200, 'bandpass', 0.7, AU.musBus);
    const c = AU.ctx, o = c.createOscillator(), g = c.createGain();
    o.type = 'triangle'; o.frequency.setValueAtTime(200, t);
    g.gain.setValueAtTime(0.1, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.08);
    o.connect(g); g.connect(AU.musBus); o.start(t); o.stop(t + 0.1);
  }
};

