function rockArt(g, r) {
  const n = rndi(8, 11), pts = [];
  for (let i = 0; i < n; i++) { const a = (i / n) * TAU, rr = r * rnd(0.8, 1.12); pts.push([Math.cos(a) * rr, Math.sin(a) * rr, a]); }
  P(g, 'M' + pts.map(q => f1(q[0]) + ' ' + f1(q[1])).join('L') + 'Z', pick(['#a0785a', '#8e7aa8', '#9a8a70', '#b07a5a']), 3);
  let d = 'M0 0';
  for (const q of pts) if (q[2] < 2.3) d += 'L' + f1(q[0] * 0.95) + ' ' + f1(q[1] * 0.95);
  P(g, d + 'Z', 'url(#ht)');
  for (let k = 0; k < (r > 20 ? 3 : 1); k++) E(g, f1(rnd(-r * 0.45, r * 0.3)), f1(rnd(-r * 0.45, r * 0.3)), f1(r * rnd(0.14, 0.22)), f1(r * rnd(0.1, 0.17)), 'rgba(40,20,30,0.28)', 2);
  return {};
}
