// ================================================================ scrolling backgrounds
function Scroller(parent, h, mul, gen) { this.g = grp(parent); this.h = h; this.mul = mul; this.gen = gen; this.chunks = new Map(); }
Scroller.prototype.update = function (S) {
  const off = S * this.mul, h = this.h;
  const kMin = Math.floor(off / h), kMax = Math.floor((off + FH) / h);
  for (const [k, c] of this.chunks) if (k < kMin || k > kMax) { c.remove(); this.chunks.delete(k); }
  for (let k = kMin; k <= kMax; k++) if (!this.chunks.has(k)) {
    const c = grp(this.g, 'translate(0 ' + (FH - (k + 1) * h) + ')');
    this.gen(c, k);
    this.chunks.set(k, c);
  }
  this.g.setAttribute('transform', 'translate(0 ' + f1(off) + ')');
};
const CITY_COLS = ['#f2a65a', '#7fc8c0', '#e56b6f', '#f6d55c', '#9d8df1', '#8ecae6', '#f4978e', '#b5e48c'];
function building(g, x, y, w, h) {
  const s = rnd(7, 15), col = pick(CITY_COLS);
  P(g, 'M' + f1(x + w) + ' ' + f1(y + 3) + 'l' + f1(s) + ' ' + f1(s) + 'V' + f1(y + h + s) + 'H' + f1(x + s) + 'L' + f1(x) + ' ' + f1(y + h) + 'Z', 'rgba(16,14,28,0.42)');
  R(g, f1(x), f1(y), f1(w), f1(h), col, 3);
  R(g, f1(x + 5), f1(y + 5), f1(w - 10), f1(h - 10), 'none', 0, { stroke: 'rgba(21,18,28,0.45)', 'stroke-width': 2 });
  P(g, 'M' + f1(x + w) + ' ' + f1(y) + 'V' + f1(y + h) + 'H' + f1(x + w * 0.3) + 'Z', 'url(#ht)');
  const r = Math.random();
  if (r < 0.18) {
    const cx = f1(x + rnd(22, w - 22)), cy = f1(y + rnd(22, h - 22));
    C(g, cx, cy, 13, '#a0522d', 3);
    P(g, 'M' + (cx - 9) + ' ' + cy + 'H' + (cx + 9) + 'M' + cx + ' ' + (cy - 9) + 'V' + (cy + 9), 'none', 2);
  } else if (r < 0.28 && w > 76 && h > 76) {
    const cx = f1(x + w / 2), cy = f1(y + h / 2);
    C(g, cx, cy, 24, '#3f4758', 3);
    C(g, cx, cy, 18, 'none', 0, { stroke: '#fff', 'stroke-width': 2 });
    P(g, 'M' + (cx - 7) + ' ' + (cy - 9) + 'V' + (cy + 9) + 'M' + (cx + 7) + ' ' + (cy - 9) + 'V' + (cy + 9) + 'M' + (cx - 7) + ' ' + cy + 'H' + (cx + 7), 'none', 0, { stroke: YEL, 'stroke-width': 3.5 });
  } else if (r < 0.75) {
    let d = '', d2 = '';
    const n = rndi(2, 4);
    for (let i = 0; i < n; i++) { const ax = f1(x + rnd(10, w - 28)), ay = f1(y + rnd(10, h - 26)); d += 'M' + ax + ' ' + ay + 'h17v15h-17Z'; d2 += circD(ax + 8.5, ay + 7.5, 4.5); }
    P(g, d, '#c8ccd4', 2); P(g, d2, '#6b7280', 1.5);
  } else {
    let d = '';
    const cols = Math.floor((w - 20) / 20), rows = Math.min(3, Math.floor((h - 20) / 22));
    for (let i = 0; i < cols; i++) for (let j = 0; j < rows; j++) d += 'M' + f1(x + 12 + i * 20) + ' ' + f1(y + 12 + j * 22) + 'h13v14h-13Z';
    P(g, d, '#bfefff', 2);
  }
}
function genCity(g) {
  for (let row = 0; row < 2; row++) {
    const y0 = row * 180;
    R(g, 0, y0, FW, 26, '#3f4758');
    P(g, 'M0 ' + (y0 + 13) + 'H' + FW, 'none', 0, { stroke: YEL, 'stroke-width': 2.5, 'stroke-dasharray': '16 12' });
    P(g, 'M0 ' + y0 + 'H' + FW + 'M0 ' + (y0 + 26) + 'H' + FW, 'none', 2.5);
    let x = 6;
    while (x < 540) {
      let w = rnd(76, 150);
      if (x + w > 554) w = 554 - x;
      if (w < 50) break;
      if (Math.random() < 0.12) {
        R(g, f1(x), y0 + 34, f1(w - 10), 138, '#7cc36b', 3);
        P(g, 'M' + f1(x + 6) + ' ' + (y0 + 103) + 'H' + f1(x + w - 16), 'none', 0, { stroke: '#e9d8a6', 'stroke-width': 6 });
        let d = '';
        for (let i = 0; i < 5; i++) d += circD(x + rnd(14, w - 24), y0 + 34 + rnd(14, 124), f1(rnd(8, 13)));
        P(g, d, '#3f9b4a', 2.5);
      } else building(g, x, y0 + 34, w - 10, rnd(110, 138));
      x += w;
    }
    let cd = '';
    for (let i = 0; i < 2; i++) cd += 'M' + f1(rnd(10, 530)) + ' ' + (y0 + (i ? 16 : 3)) + 'h18v7h-18Z';
    P(g, cd, pick([RED, CYAN, YEL, '#fff']), 1.8);
  }
}
function genClouds(g) {
