  const cx = rnd(60, 500), cy = rnd(80, 640), rx = rnd(40, 70);
  P(g, cloudD(cx, cy, rx, rx * 0.5, 8), '#c9d2e3', 3);
  P(g, 'M' + f1(cx - rx * 0.7) + ' ' + f1(cy + rx * 0.18) + 'Q' + f1(cx) + ' ' + f1(cy + rx * 0.6) + ' ' + f1(cx + rx * 0.7) + ' ' + f1(cy + rx * 0.18) + 'Z', 'url(#ht)');
