const BG = { layers: [], planet: null };
function buildBackground(i) {
  L.bg.textContent = '';
  L.bgTop.textContent = '';
  BG.layers = [];
  BG.planet = null;
  if (i === 0) {
    L.fieldBase.setAttribute('fill', '#59667d');
    BG.layers.push(new Scroller(L.bg, 360, 1, genCity));
    R(L.bg, 0, 0, FW, FH, '#0e2248', 0, { opacity: 0.32 });
