    P(pl, 'M340 110 C400 130 470 124 526 104 M330 170 C400 194 480 188 532 170', 'none', 0, { stroke: '#e0548a', 'stroke-width': 12 });
    P(pl, 'M470 64 A104 104 0 0 1 470 256 A70 104 0 0 0 470 64 Z', 'url(#htMag)');
    P(pl, 'M252 164 A180 36 0 0 0 608 164', 'none', 0, { stroke: INK, 'stroke-width': 13 });
    P(pl, 'M252 164 A180 36 0 0 0 608 164', 'none', 0, { stroke: '#e9b949', 'stroke-width': 6 });
    BG.layers.push(new Scroller(L.bg, 360, 0.3, genStars));
    BG.layers.push(new Scroller(L.bg, 360, 0.65, genFarRocks));
    BG.layers.push(new Scroller(L.bgTop, 720, 2.4, genStreaks));
  } else {
    L.fieldBase.setAttribute('fill', '#4b5870');
    BG.layers.push(new Scroller(L.bg, 360, 1, genDeck));
    R(L.bg, 0, 0, FW, FH, '#0a0f24', 0, { opacity: 0.24 });
    BG.layers.push(new Scroller(L.bgTop, 720, 1.5, genSteam));
  }
  updBG(0);
}
function updBG(S) {
  for (const l of BG.layers) l.update(S);
  if (BG.planet) BG.planet.setAttribute('transform', 'translate(0 ' + f1(S * 0.06) + ')');
}

// ================================================================ side panels (HUD)
function bubbleD(x, y, w, h, tx, ty) {
  const r = 14, bx = clamp(tx + 14, x + r + 4, x + w - r - 26);
  return 'M' + (x + r) + ' ' + y + 'H' + (x + w - r) + 'Q' + (x + w) + ' ' + y + ' ' + (x + w) + ' ' + (y + r) + 'V' + (y + h - r) +
    'Q' + (x + w) + ' ' + (y + h) + ' ' + (x + w - r) + ' ' + (y + h) + 'H' + (bx + 20) + 'L' + tx + ' ' + ty + 'L' + bx + ' ' + (y + h) +
    'H' + (x + r) + 'Q' + x + ' ' + (y + h) + ' ' + x + ' ' + (y + h - r) + 'V' + (y + r) + 'Q' + x + ' ' + y + ' ' + (x + r) + ' ' + y + 'Z';
}
function weaponIcon(g, i) {
  if (i === 0) P(g, 'M-4 -22 h8 v28 h-8 Z', YEL, 2.5);
  else if (i === 1) P(g, 'M-13 -22 h8 v28 h-8 Z M5 -22 h8 v28 h-8 Z', YEL, 2.5);
  else if (i === 2) { for (const a of [-44, -22, 0, 22, 44]) P(g, 'M-3.5 -24 h7 v18 h-7 Z', ORG, 2, { transform: 'rotate(' + a + ' 0 12)' }); }
  else { R(g, -8, -28, 16, 42, CYAN, 2.5); R(g, -3, -28, 6, 42, '#fff'); }
  P(g, 'M-10 22 L0 12 L10 22 Z', '#5b6275', 2);
}
