const HV = {};
const PILOT = { t: 0, bubT: 0 };
function pilotSay(expr, text, dur) {
  HUD.pilot.set(expr);
  PILOT.t = dur || 2.4;
  if (text) {
    const lines = splitLines(text, 8);
    const two = lines.length > 1;
    HUD.bubPath.setAttribute('d', bubbleD(190, 172, 148, two ? 66 : 44, 168, 292));
    sa(HUD.bubT1, { y: two ? 199 : 200 });
    HUD.bubT1.textContent = lines[0];
    sa(HUD.bubT2, { y: 222 });
    HUD.bubT2.textContent = two ? lines[1] : '';
    show(HUD.bub, true);
    PILOT.bubT = Math.max(2.6, dur || 0);
  }
}
function updPilot(dt) {
  if (PILOT.t > 0) { PILOT.t -= dt; if (PILOT.t <= 0) HUD.pilot.set(G.lives === 1 ? 'worried' : 'normal'); }
  if (PILOT.bubT > 0) { PILOT.bubT -= dt; if (PILOT.bubT <= 0) show(HUD.bub, false); }
}
function updHUD() {
  if (HV.score !== G.score) { HV.score = G.score; HUD.score.set(String(G.score).padStart(8, '0')); }
  const hi = Math.max(HI[G.diff] || 0, G.score);
  if (HV.hi !== hi) { HV.hi = hi; HUD.hi.set(String(hi).padStart(8, '0')); }
  if (HV.lives !== G.lives) { HV.lives = G.lives; HUD.lives.forEach((n, i) => show(n, i < G.lives)); }
  if (HV.bombs !== G.bombs) { HV.bombs = G.bombs; HUD.bombs.forEach((n, i) => show(n, i < G.bombs)); }
  if (HV.shield !== G.shield) {
    HV.shield = G.shield;
    HUD.shieldIcon.setAttribute('opacity', G.shield ? 1 : 0.25);
    HUD.shieldT.textContent = G.shield ? '已就绪' : '无';
    HUD.shieldT.setAttribute('fill', G.shield ? '#0a7fb8' : '#8a8a8a');
  }
  if (HV.power !== G.power) {
    HV.power = G.power;
    HUD.lv.set('LV.' + G.power);
    HUD.wbox.forEach((w, i) => {
      const on = i === G.power - 1, got = i < G.power;
      w.box.setAttribute('fill', on ? RED : got ? '#fff' : '#d9d2c0');
      w.lab.setAttribute('fill', on ? '#fff' : got ? INK : '#8a8a8a');
      w.ic.setAttribute('opacity', got ? 1 : 0.35);
    });
  }
  const en = Math.floor(G.energy);
  if (HV.en !== en) {
    HV.en = en;
    HUD.enPct.set(en + '%');
    const lit = Math.floor(en / 10);
    HUD.seg.forEach((s, i) => s.setAttribute('fill', en >= 100 ? YEL : i < lit ? '#ff9ad0' : '#5a2346'));
    show(HUD.readyG, en >= 100);
    show(HUD.chargeT, en < 100);
  }
  if (en >= 100) {
    const on = Math.sin(G.rt * 10) > -0.3;
    if (HV.blink !== on) { HV.blink = on; HUD.readyG.setAttribute('opacity', on ? 1 : 0.35); }
  }
  if (HV.graze !== G.grazeAll) { HV.graze = G.grazeAll; HUD.graze.set(String(G.grazeAll)); }
  if (HV.diff !== G.diff) { HV.diff = G.diff; HUD.diffT.textContent = '难度：' + DIFFS[G.diff].name; }
  if (HV.stage !== G.stage) {
    HV.stage = G.stage;
    HUD.stageN.textContent = '第 ' + (G.stage + 1) + ' / 3 话';
    HUD.stageT.textContent = '第' + (G.stage + 1) + '话 · ' + STAGES[G.stage].name;
  }
  if (HV.mute !== AU.muted) { HV.mute = AU.muted; HUD.muteT.textContent = 'M 静音：' + (AU.muted ? '开' : '关'); }
}

// ================================================================ menus and screens
function makeMenu(parent, x, y, gap, labels, onPick, o) {
  o = o || {};
  const w = o.w || 240, size = o.size || 30;
  const m = { items: [], sel: 0 };
  labels.forEach((lab, i) => {
    const g = grp(parent, 'translate(' + x + ' ' + (y + i * gap) + ')');
    const hl = P(g, 'M-14 ' + (-size - 8) + ' L' + w + ' ' + (-size - 12) + ' L' + (w + 8) + ' ' + (size * 0.36) + ' L-6 ' + (size * 0.5) + ' Z', YEL, 3.5);
    const arrow = P(g, 'M-40 ' + (-size * 0.75) + ' L-22 ' + (-size * 0.38) + ' L-40 0 Z', RED, 2.5);
    const t = T(g, 6, 0, lab, size, INK);
    const hit = R(g, -44, -size - 14, w + 60, size + 26, 'transparent', 0, { class: 'btn' });
    hit.addEventListener('click', () => { AU.init(); m.sel = i; m.refresh(); onPick(i); });
    m.items.push({ g, hl, arrow, t });
  });
  m.refresh = () => m.items.forEach((it, i) => { show(it.hl, i === m.sel); show(it.arrow, i === m.sel); });
  m.move = d => { m.sel = (m.sel + d + m.items.length) % m.items.length; m.refresh(); AU.play('move'); };
  m.refresh();
  return m;
}
function menuKey(m, a, onPick) {
  if (a === 'up') m.move(-1);
  else if (a === 'down') m.move(1);
  else if (a === 'enter' || a === 'fire') onPick(m.sel);
}
