const PATHS = {
  sweep: [[-40, 70], [120, 150], [280, 196], [440, 150], [610, 60]],
  swirl: [[90, -40], [110, 140], [220, 280], [380, 270], [420, 160], [320, 100], [230, 190], [270, 360], [420, 540], [600, 780]],
  zig: [[110, -40], [440, 150], [120, 330], [440, 510], [300, 790]],
  uturn: [[130, -40], [130, 260], [190, 390], [300, 400], [380, 300], [400, 120], [400, -70]],
  hook: [[-40, 220], [160, 250], [300, 210], [330, 110], [250, 50], [180, 130], [240, 400], [260, 790]]
};
const PATH_CACHE = {};
function getPath(name, mirror) {
  const key = name + (mirror ? 'M' : '');
  if (PATH_CACHE[key]) return PATH_CACHE[key];
  const src = PATHS[name].map(p => (mirror ? [FW - p[0], p[1]] : p));
  const pts = [];
  for (let i = 0; i < src.length - 1; i++) {
    const p0 = src[Math.max(0, i - 1)], p1 = src[i], p2 = src[i + 1], p3 = src[Math.min(src.length - 1, i + 2)];
    for (let s = 0; s < 14; s++) {
      const t = s / 14, t2 = t * t, t3 = t2 * t;
      const cr = j => 0.5 * (2 * p1[j] + (-p0[j] + p2[j]) * t + (2 * p0[j] - 5 * p1[j] + 4 * p2[j] - p3[j]) * t2 + (-p0[j] + 3 * p1[j] - 3 * p2[j] + p3[j]) * t3);
      pts.push([cr(0), cr(1)]);
    }
  }
  pts.push(src[src.length - 1]);
  const Ls = [0];
  for (let i = 1; i < pts.length; i++) Ls.push(Ls[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));
  return (PATH_CACHE[key] = { pts, L: Ls, total: Ls[Ls.length - 1] });
}
