    for (let i = 0; i < n; i++) {
      const off = i - (n - 1) / 2;
      spawn(o.type || 'buzz', { mv: 'drop', x: o.x + off * 42, y: -30 - Math.abs(off) * 34, vy: o.vy || 100, amp: o.amp || 0, fire: o.fire || 'aim1', fcd: rnd(0.8, 2), fint: o.fint || 2.4, grp: gid });
    }
  },
  path(o) {
