  },
  dive(o) { o.xs.forEach((x, i) => later(i * (o.gap || 0.5), () => spawn(o.type || 'swoop', { mv: 'dive', x, y: -30, y1: rnd(110, 220), t1: 1.0, dsp: o.spd || 270 }))); },
  hover(o) { spawn(o.type || 'pod', { mv: 'hover', x: o.x, y: -40, ty: o.y, hold: o.hold || 5, fire: o.fire || 'ring', fcd: 1.1, fint: o.fint || 1.7, drop: o.drop }); },
  turrets(o) { o.xs.forEach(x => spawn('turret', { mv: 'ground', x, y: -30, fire: 'turret', fcd: rnd(0.6, 1.4), fint: o.fint || 1.9, drop: o.drop })); },
  carrier(o) { spawn('carrier', { mv: 'lin', x: o.x, y: -40, vx: o.vx || 0, vy: 62, drop: o.drop || 'P' }); },
  heavy(o) { spawn('heavy', { mv: 'hover', x: o.x, y: -70, ty: o.y || 150, hold: o.hold || 13, fire: 'heavy', fcd: 1.4, fint: 1.35, drop: o.drop, sway: 70 }); },
  rocks(o) { for (let i = 0; i < (o.n || 1); i++) later(i * (o.gap || 0.4), () => spawnRock(Math.random() < 0.4)); },
