function spawnRock(big) { spawn(big ? 'rock' : 'rockS', { mv: 'lin', x: rnd(40, FW - 40), y: -40, vx: rnd(-40, 40), vy: rnd(70, 130), vr: rnd(-90, 90) }); }
function spawn(type, o) {
  const T0 = ET[type];
  const e = Object.assign({ type, T: T0, x: 280, y: -30, t: 0, rot: 0, r: T0.r, hp: T0.hp * G.D.hp, flash: 0, fcd: 1, entered: false, dead: false, air: !T0.ground }, o);
  e.x0 = e.x; e.y0 = e.y;
  e.g = grp(e.air ? L.enemies : L.ground);
  const art = T0.sc ? grp(e.g, 'scale(' + T0.sc + ')') : e.g;
