}
function aimAt(x, y) { return Math.atan2(PL.y - y, PL.x - x); }
function cnt(n) { return Math.max(1, Math.round(n * G.D.dens)); }
function shoot(x, y, a, spd, type, o) {
  if (EB.length > 700) return null;
  const s = spd * G.D.bs;
  const b = { x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s, type, hr: BT[type].hr, r: BT[type].r, t: 0, grazed: false, dead: false };
