function fan(x, y, a0, n, spread, spd, type, o) { for (let i = 0; i < n; i++) shoot(x, y, a0 + (i - (n - 1) / 2) * spread, spd, type, o); }
function ring(x, y, n, spd, type, off, o) { for (let i = 0; i < n; i++) shoot(x, y, off + (i * TAU) / n, spd, type, o); }
const EFIRE = {
  aim1(e) { shoot(e.x, e.y + 8, aimAt(e.x, e.y), 165, 0); },
  aim2(e) { fan(e.x, e.y + 8, aimAt(e.x, e.y), cnt(2), 0.18, 170, 0); },
  dive3(e) { fan(e.x, e.y, aimAt(e.x, e.y), cnt(3), 0.26, 190, 0); },
  needle(e) { const a = aimAt(e.x, e.y); for (let i = 0; i < cnt(3); i++) later(i * 0.08, () => { if (!e.dead) shoot(e.x, e.y + 10, a, 250, 3); }); },
  ring(e) { ring(e.x, e.y, cnt(12), 115, 1, rnd(0, TAU)); },
  ring2(e) { const n = cnt(10), o = rnd(0, TAU); ring(e.x, e.y, n, 110, 0, o); later(0.22, () => { if (!e.dead) ring(e.x, e.y, n, 145, 0, o + PI / n); }); },
  spiral(e) { e.sa = (e.sa || 0) + 0.45; const n = cnt(3); for (let k = 0; k < n; k++) shoot(e.x, e.y, e.sa + (k * TAU) / n, 130, 4); },
  turret(e) { const a = aimAt(e.x, e.y); fan(e.x + Math.cos(a) * 22, e.y + Math.sin(a) * 22, a, G.stage === 2 ? cnt(2) : 1, 0.14, 175, 0); },
  heavy(e) {
    e.hc = (e.hc || 0) + 1;
    if (e.hc % 3 === 0) ring(e.x, e.y + 10, cnt(16), 115, 1, rnd(0, TAU));
    else for (const s of [-1, 1]) { const tx = e.x + s * 30, ty = e.y - 6; fan(tx, ty, aimAt(tx, ty), cnt(3), 0.22, 170, 0); }
  }
};
function updEnemies(dt) {
  for (const e of EN) {
    if (e.dead) continue;
    e.t += dt;
    switch (e.mv) {
      case 'path': {
        e.s = (e.s || 0) + e.spd * dt;
        const p = e.path;
        if (e.s >= p.total) { e.dead = true; e.escaped = true; break; }
        let i = e.pi || 0;
        while (i < p.L.length - 2 && p.L[i + 1] < e.s) i++;
        e.pi = i;
        const a = p.pts[i], b = p.pts[i + 1], k = (e.s - p.L[i]) / ((p.L[i + 1] - p.L[i]) || 1);
        e.x = a[0] + (b[0] - a[0]) * k;
        e.y = a[1] + (b[1] - a[1]) * k;
        e.rot = (Math.atan2(b[1] - a[1], b[0] - a[0]) * 180) / PI - 90;
        break;
      }
      case 'drop':
