        else if (!e.dv) {
          e.dv = true;
          const a = aimAt(e.x, e.y);
          e.vx = Math.cos(a) * e.dsp;
          e.vy = Math.max(90, Math.sin(a) * e.dsp);
          if (e.y < 420 && PL.alive) EFIRE.dive3(e);
        } else {
          e.x += e.vx * dt; e.y += e.vy * dt; e.vy += 80 * dt;
          e.rot = (Math.atan2(e.vy, e.vx) * 180) / PI - 90;
        }
        break;
      case 'hover': {
        const te = 1.5;
        if (e.t < te) e.y = lerp(e.y0, e.ty, easeOut(e.t / te));
        else if (e.t < te + e.hold) { e.y = e.ty + Math.sin((e.t - te) * 1.6) * 6; if (e.sway) e.x = e.x0 + Math.sin((e.t - te) * 0.6) * e.sway; }
        else { e.vy = (e.vy || 0) - 170 * dt; e.y += e.vy * dt; e.nofire = true; }
        break;
      }
      case 'ground': e.y += G.scrollSpd * dt; break;
      case 'lin': e.x += (e.vx || 0) * dt; e.y += (e.vy || 0) * dt; e.rot += (e.vr || 0) * dt; break;
    }
    if (e.dead) continue;
    if (!e.entered) {
      if (e.y > 4 && e.y < FH && e.x > -10 && e.x < FW + 10) e.entered = true;
      else if (e.t > 14) { e.dead = true; e.escaped = true; continue; }
    }
    if (e.entered && (e.y > FH + 70 || e.y < -100 || e.x < -100 || e.x > FW + 100)) { e.dead = true; e.escaped = true; continue; }
    if (e.fire && e.entered && !e.nofire && e.y < 470 && PL.alive && G.phase !== 'bossDead') {
      e.fcd -= dt;
      if (e.fcd <= 0) { e.fcd = ((e.fint || 2) / G.D.rate) * rnd(0.85, 1.2); EFIRE[e.fire](e); }
