  });
}
function placeEnemy(e) {
  let tf = 'translate(' + f1(e.x) + ' ' + f1(e.y) + ')';
  if (e.rot) tf += ' rotate(' + f1(e.rot) + ')';
  e.g.setAttribute('transform', tf);
  const pt = e.parts;
  if (pt.tur) pt.tur.setAttribute('transform', 'rotate(' + f1((Math.atan2(PL.y - e.y, PL.x - e.x) * 180) / PI - 90 - (e.rot || 0)) + ')');
  if (pt.turs) for (let i = 0; i < 2; i++) { const s = i ? 1 : -1; pt.turs[i].setAttribute('transform', 'rotate(' + f1((Math.atan2(PL.y - e.y + 6, PL.x - e.x - s * 30) * 180) / PI - 90) + ')'); }
  if (pt.props) { const sx = Math.abs(Math.sin(e.t * 30)).toFixed(2); for (const pr of pt.props) pr.setAttribute('transform', 'scale(' + sx + ' 1)'); }
}
function hitEnemy(e, dmg, cont) {
  if (e.dead) return;
  e.hp -= dmg;
