  if (e.hp <= 0) killEnemy(e);
}
function killEnemy(e) {
  if (e.dead) return;
  e.dead = true;
  if (!e.T.nc) { G.stats.killed++; G.killsAll++; }
  addScore(e.T.score);
  const k = e.T.kind;
  if (k === 'b') {
    boom(e.x, e.y, 72, pick(WORDS.b));
    const x = e.x, y = e.y;
    later(0.12, () => boom(x + rnd(-34, 34), y + rnd(-24, 24), 40, null));
    later(0.26, () => boom(x + rnd(-34, 34), y + rnd(-24, 24), 46, null));
    shakeIt(9); AU.play('boom');
  } else if (k === 'm') { boom(e.x, e.y, 42, pick(WORDS.m)); shakeIt(3); AU.play('boom'); }
  else { boom(e.x, e.y, 26, Math.random() < 0.5 ? pick(WORDS.s) : null); AU.play('pop'); }
  if (e.drop) spawnItem(e.drop, e.x, e.y);
  if (e.grp) groupGone(e, true);
  if (e.type === 'rock') for (let i = 0; i < 3; i++) spawn('rockS', { mv: 'lin', x: e.x, y: e.y, vx: rnd(-90, 90), vy: rnd(40, 120), vr: rnd(-120, 120), entered: true });
}

// ================================================================ player
function pshot(x, y, vx, vy, k, dmg) { PS.push({ x, y, vx, vy, k, dmg, dead: false }); }
function firePlayer() {
  const p = PL, lv = G.power;
  if (lv === 1) { pshot(p.x, p.y - 30, 0, -920, 'v', 1.6); p.fireT = 0.075; }
  else if (lv === 2) { pshot(p.x - 8, p.y - 26, 0, -920, 'v', 1.2); pshot(p.x + 8, p.y - 26, 0, -920, 'v', 1.2); p.fireT = 0.075; }
  else if (lv === 3) {
    const spr = p.focus ? 0.45 : 1;
    pshot(p.x - 6, p.y - 28, 0, -920, 'v', 1); pshot(p.x + 6, p.y - 28, 0, -920, 'v', 1);
    for (const k of [1, 2]) for (const s of [-1, 1]) { const a = -PI / 2 + s * k * 0.19 * spr; pshot(p.x + s * 10, p.y - 16, Math.cos(a) * 840, Math.sin(a) * 840, 's', 0.75); }
    p.fireT = 0.1;
  } else {
    for (const s of [-1, 1]) { const a = -PI / 2 + s * (p.focus ? 0.07 : 0.2); pshot(p.x + s * 17, p.y - 8, Math.cos(a) * 860, Math.sin(a) * 860, 'm', 0.9); }
    p.fireT = 0.11;
  }
  AU.play(lv >= 4 ? 'laser' : 'shot');
}
function updPlayer(dt) {
  const p = PL;
  if (!p.alive) {
    G.wantBomb = G.wantSpecial = false;
    p.respawn -= dt;
    if (p.respawn <= 0 && G.lives > 0) { p.alive = true; p.x = 280; p.y = 790; p.enterT = 0.9; p.inv = 3.2; p.respInv = 3.2; }
    return;
  }
  if (p.inv > 0) p.inv -= dt;
  if (p.respInv > 0) p.respInv -= dt;
  if (p.enterT > 0) {
    p.enterT -= dt;
    p.y = 640 + (Math.max(0, p.enterT) / 0.9) * 150;
    p.bank = 0; p.laser = false;
    G.wantBomb = G.wantSpecial = false;
    return;
  }
  p.focus = !!K.focus;
  const sp = (p.focus ? 140 : 300) * (p.specT > 0 ? 0.55 : 1);
  let dx = (K.right ? 1 : 0) - (K.left ? 1 : 0), dy = (K.down ? 1 : 0) - (K.up ? 1 : 0);
  if (dx && dy) { dx *= 0.7071; dy *= 0.7071; }
  p.x = clamp(p.x + dx * sp * dt, 20, FW - 20);
  p.y = clamp(p.y + dy * sp * dt, 40, FH - 30);
  p.bank = lerp(p.bank, dx, Math.min(1, dt * 12));
  const canFire = G.mode === 'play' && G.phase !== 'bossDead';
  p.fireT -= dt;
  if (K.fire && canFire && p.fireT <= 0) firePlayer();
