  }
  if (p.specT > 0) p.specT -= dt;
  if (G.wantBomb) { G.wantBomb = false; doBomb(); }
  if (G.wantSpecial) { G.wantSpecial = false; doSpecial(); }
}
function doBomb() {
  const p = PL;
  if (G.bombs <= 0 || p.bombT > 0 || !p.alive || p.enterT > 0 || G.mode !== 'play') return;
  G.bombs--;
  p.bombT = 1.3;
  p.inv = Math.max(p.inv, 2.6);
  G.flash = 0.45;
  shakeIt(16);
  boom(280, clamp(p.y - 190, 220, 470), 240, 'KA-BLAM!!', RED);
  for (const b of EB) if (!b.dead) { b.dead = true; addScore(10); }
  for (const e of EN) if (!e.dead && e.entered) hitEnemy(e, 45);
  if (G.boss && G.boss.state === 'fight') hitBoss(G.boss, 70);
  AU.play('bomb');
  pilotSay('shout', '吃我一炸！');
}
function doSpecial() {
  const p = PL;
  if (G.energy < 100 || p.specT > 0 || !p.alive || p.enterT > 0 || G.mode !== 'play') return;
  G.energy = 0;
  p.specT = 3.2;
  p.inv = Math.max(p.inv, 3.6);
  G.slow = 0.75;
  G.cutT = 0;
  show(SC.cut, true);
  AU.play('special');
  pilotSay('shout', '必杀·星爆光束！');
}
function graze(b) {
  G.stats.graze++; G.grazeAll++;
  addScore(20);
  const was = G.energy;
  G.energy = Math.min(100, G.energy + G.D.graze);
  if (was < 100 && G.energy >= 100) { AU.play('ready'); pilotSay('grin', '能量满了！按 C 必杀！'); pop('READY!', PL.x, PL.y - 50, MAG, 20); }
  spark((b.x + PL.x) / 2, (b.y + PL.y) / 2, 2, 120, 2);
  AU.play('graze');
}
function playerHit() {
  const p = PL;
  if (p.inv > 0 || G.god || !p.alive) return;
  if (G.shield) {
    G.shield = false;
    p.inv = 1.3; p.respInv = 1.3;
    for (const b of EB) if (!b.dead && (b.x - p.x) * (b.x - p.x) + (b.y - p.y) * (b.y - p.y) < 14400) { b.dead = true; spark(b.x, b.y, 1, 90, 2); }
    boom(p.x, p.y - 8, 36, 'CLANG!', CYAN);
    shakeIt(6);
    AU.play('shield');
    pilotSay('hurt', '好险！护盾挡住了！');
    return;
  }
