  spark(p.x, p.y, 22, 420, 0);
  shakeIt(14);
  G.flash = 0.35;
  AU.play('die');
  p.alive = false; p.respawn = 1.5; p.specT = 0; p.bombT = 0; p.laser = false;
  G.lives--; G.stats.hits++;
  for (const b of EB) b.dead = true;
  if (G.power > 1) { G.power--; spawnItem('P', p.x, Math.min(p.y - 40, 560)); }
  G.bombs = Math.max(G.bombs, G.D.bombs);
  if (G.lives <= 0) { pilotSay('dizzy', '呜哇——！', 6); later(2.2, gameOver); }
  else pilotSay('hurt', pick(['哎哟！还没完呢！', '可恶，被打中了！', '再来！我还能飞！']), 2.6);
}
function updShots(dt) {
  for (const s of PS) {
    s.x += s.vx * dt; s.y += s.vy * dt;
    if (s.y < -30 || s.x < -20 || s.x > FW + 20) { s.dead = true; continue; }
    for (const e of EN) {
      if (e.dead || !e.entered) continue;
      const dx = e.x - s.x, dy = e.y - s.y, rr = e.r + 5;
      if (dx * dx + dy * dy < rr * rr) { hitEnemy(e, s.dmg); s.dead = true; if (Math.random() < 0.5) spark(s.x, s.y, 2, 160, 0); break; }
    }
    if (!s.dead && G.boss && G.boss.hit(s.x, s.y, 4)) { hitBoss(G.boss, s.dmg); s.dead = true; if (Math.random() < 0.4) spark(s.x, s.y + 4, 2, 170, 0); }
  }
  compact(PS, s => !s.dead);
  const p = PL;
  if (p.laser && p.alive) {
    const hw = 11;
    for (const e of EN) if (!e.dead && e.entered && e.y < p.y && Math.abs(e.x - p.x) < e.r + hw) { hitEnemy(e, 44 * dt, true); if (Math.random() < 0.15) spark(e.x + rnd(-6, 6), e.y + e.r * 0.5, 1, 160, 2); }
    if (G.boss && G.boss.col(p.x, hw) && G.boss.y < p.y) { hitBoss(G.boss, 44 * dt, true); if (Math.random() < 0.2) spark(p.x + rnd(-6, 6), G.boss.y + 60, 1, 160, 2); }
  }
  if (p.specT > 0 && p.specT < 2.6 && p.alive) {
    const hw = 62;
    for (const e of EN) if (!e.dead && e.entered && e.y < p.y + 20 && Math.abs(e.x - p.x) < e.r + hw) hitEnemy(e, 320 * dt, true);
    if (G.boss && G.boss.col(p.x, hw)) hitBoss(G.boss, 150 * dt, true);
    for (const b of EB) if (!b.dead && b.y < p.y + 10 && Math.abs(b.x - p.x) < hw + b.r) { b.dead = true; addScore(10); if (Math.random() < 0.4) spark(b.x, b.y, 1, 120, 0); }
    shakeIt(3);
  }
}
function updBullets(dt) {
  const p = PL, hr = G.D.hitR, vuln = p.alive && p.enterT <= 0, inv = p.inv > 0 || G.god;
  for (const b of EB) {
    if (b.dead) continue;
    b.t += dt;
    if (b.ay) b.vy = Math.min(230, b.vy + b.ay * dt);
    b.x += b.vx * dt; b.y += b.vy * dt;
    if (b.split && b.t >= b.split) { b.dead = true; ring(b.x, b.y, b.sn, b.ss, b.st, rnd(0, TAU)); spark(b.x, b.y, 5, 200, 0); continue; }
    if (b.x < -30 || b.x > FW + 30 || b.y > FH + 30 || b.y < (b.ay ? -400 : -40)) { b.dead = true; continue; }
    if (!vuln) continue;
    const dx = b.x - p.x, dy = b.y - p.y, d2 = dx * dx + dy * dy, hd = hr + b.hr;
    if (d2 < hd * hd) { if (!inv) { b.dead = true; playerHit(); } continue; }
    if (!b.grazed && !inv) { const gd = hd + 17; if (d2 < gd * gd) { b.grazed = true; graze(b); } }
  }
  compact(EB, b => !b.dead);
}
function updCollide() {
  const p = PL;
  if (!p.alive || p.enterT > 0 || p.inv > 0 || G.god) return;
  const hr = G.D.hitR;
  for (const e of EN) {
    if (e.dead || !e.air || !e.entered) continue;
    const rr = e.r * 0.62 + hr, dx = e.x - p.x, dy = e.y - p.y;
    if (dx * dx + dy * dy < rr * rr) { playerHit(); if (e.T.kind === 's') killEnemy(e); return; }
  }
  if (G.boss && G.boss.state === 'fight' && G.boss.hit(p.x, p.y, -8)) playerHit();
}

// ================================================================ items, effects
function spawnItem(type, x, y) {
  const g = grp(L.items);
  buildItem(g, type);
  const it = { type, x: clamp(x, 30, FW - 30), y: Math.min(y, FH - 140), vx: rnd(-40, 40), vy: -120, t: 0, g };
  IT.push(it);
  it.g.setAttribute('transform', 'translate(' + f1(it.x) + ' ' + f1(it.y) + ')');
}
function updItems(dt) {
  const p = PL;
  for (const it of IT) {
    it.t += dt;
    it.vy = Math.min(72, it.vy + 170 * dt);
    it.x += it.vx * dt; it.y += it.vy * dt;
    if ((it.x < 24 && it.vx < 0) || (it.x > FW - 24 && it.vx > 0)) it.vx *= -1;
    if (it.y > FH + 30) it.dead = true;
    else if (p.alive && p.enterT <= 0 && Math.abs(it.x - p.x) < 30 && Math.abs(it.y - p.y) < 32) { it.dead = true; collect(it); }
  }
  compact(IT, it => { if (it.dead) it.g.remove(); return !it.dead; });
}
function collect(it) {
  if (it.type === 'P') {
    if (G.power < 4) {
      G.power++;
      pop(['', '', 'TWIN!', 'SPREAD!', 'LASER!'][G.power], it.x, it.y - 24, YEL, 20);
      pilotSay('grin', ['', '', '火力升级：双发！', '火力升级：散射！', '火力全开：激光！'][G.power]);
      AU.play('power');
    } else { addScore(5000); pop('+5000', it.x, it.y - 24, YEL, 18); AU.play('item'); }
  } else if (it.type === 'B') {
    if (G.bombs < 6) G.bombs++; else addScore(3000);
    pop('BOMB+1', it.x, it.y - 24, ORG, 18);
    AU.play('item');
  } else {
    if (G.shield) addScore(3000);
    G.shield = true;
    pop('SHIELD!', it.x, it.y - 24, CYAN, 18);
    pilotSay('grin', '护盾上线！');
    AU.play('shield');
  }
}
function boom(x, y, size, word, col) {
  const g = grp(L.fx);
  const burst = grp(g, 'rotate(' + rndi(0, 359) + ')');
  const n = size > 60 ? 14 : 11;
  P(burst, starD(n, size, size * 0.56, 0.2), YEL, size > 50 ? 4 : 3);
  P(burst, starD(n - 2, size * 0.64, size * 0.36, 0.22), col || ORG, 2.5);
  C(burst, 0, 0, f1(size * 0.22), '#fff');
  if (word) comic(g, word, { size: f1(clamp(size * 0.42, 13, 60)), fill: '#fff', rot: rndi(-14, 14), y: f1(size * 0.16), weight: 1.4 });
  const f = { g, x, y, t: 0, life: size > 100 ? 1.1 : size > 55 ? 0.8 : 0.5 };
  FXS.push(f);
  placeFx(f);
  spark(x, y, size > 55 ? 16 : 7, size * 6);
}
function teleLine(x, y, a, life) {
  const g = grp(L.fx);
  P(g, 'M' + f1(x) + ' ' + f1(y) + 'L' + f1(x + Math.cos(a) * 900) + ' ' + f1(y + Math.sin(a) * 900), 'none', 0, { stroke: RED, 'stroke-width': 3, 'stroke-dasharray': '14 10' });
  FXS.push({ g, x: 0, y: 0, t: 0, life, line: true });
}
function placeFx(f) {
  const k = f.t / f.life;
  const s = k < 0.18 ? 0.25 + easeBack(k / 0.18) * 0.85 : k > 0.72 ? 1.1 * (1 - easeIn((k - 0.72) / 0.28)) : 1.1;
  f.g.setAttribute('transform', 'translate(' + f1(f.x) + ' ' + f1(f.y) + ') scale(' + Math.max(0.01, s).toFixed(3) + ')');
}
function updFx(dt) {
  for (const f of FXS) {
    f.t += dt;
    if (f.t >= f.life) { f.dead = true; f.g.remove(); }
    else if (f.line) f.g.setAttribute('opacity', Math.floor(f.t * 16) % 2 ? 0.35 : 1);
    else placeFx(f);
  }
  compact(FXS, f => !f.dead);
}
function pop(str, x, y, col, size) {
  const c = comic(L.pops, str, { size: size || 18, fill: col || YEL });
  const p = { c, x: clamp(x, 70, FW - 70), y, t: 0 };
  POPS.push(p);
  c.g.setAttribute('transform', 'translate(' + f1(p.x) + ' ' + f1(p.y) + ') scale(0.4)');
}
function updPops(dt) {
  for (const p of POPS) {
    p.t += dt; p.y -= 40 * dt;
    if (p.t > 1) { p.dead = true; p.c.g.remove(); continue; }
    const s = p.t < 0.12 ? 0.4 + (p.t / 0.12) * 0.8 : p.t > 0.8 ? 1.2 * (1 - (p.t - 0.8) / 0.2) : 1.2 - (p.t - 0.12) * 0.25;
    p.c.g.setAttribute('transform', 'translate(' + f1(p.x) + ' ' + f1(p.y) + ') scale(' + Math.max(0.01, s).toFixed(2) + ')');
  }
  compact(POPS, p => !p.dead);
}
function spark(x, y, n, spd, c) {
  for (let i = 0; i < n && PARTS.length < 420; i++) {
    const a = rnd(0, TAU), s = rnd(0.35, 1) * spd;
    PARTS.push({ x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s, t: 0, life: rnd(0.22, 0.5), c: c || 0 });
  }
}
function updParts(dt) {
  const damp = Math.max(0, 1 - 3 * dt);
  for (const p of PARTS) { p.t += dt; p.x += p.vx * dt; p.y += p.vy * dt; p.vx *= damp; p.vy *= damp; }
  compact(PARTS, p => p.t < p.life);
}

// ================================================================ bosses
function every(b, key, iv, fn) {
  iv /= G.D.rate;
  let c = b.cd[key];
  if (c === undefined) c = Math.min(iv * 0.5, 0.8);
  c -= b.dt;
  let guard = 0;
  while (c <= 0 && guard++ < 4) { c += iv; fn(); }
  b.cd[key] = c;
}
function bossAim(b, i, ox, oy) { return (Math.atan2(PL.y - b.y - oy, PL.x - b.x - ox) * 180) / PI - 90; }
const BOSSES = [
  { name: '钢铁巨鲸', en: 'STEEL WHALE', hp: 1300, y0: 178, score: 30000, th: [0.66, 0.33], build: buildWhale,
    lines: ['它要喷水了！', '巨鲸发狂了！小心！'],
    hit(b, x, y, r) { const dx = (x - b.x) / (150 + r), dy = (y - b.y + 6) / (98 + r); return dx * dx + dy * dy < 1; },
    col(b, x, hw) { return Math.abs(x - b.x) < 150 + hw; },
    move(b) { b.mt = (b.mt || 0) + b.dt * (b.phase === 2 ? 0.85 : 0.55); b.x = lerp(b.x, 280 + Math.sin(b.mt) * 105, Math.min(1, b.dt * 3)); b.y = lerp(b.y, this.y0 + Math.sin(b.mt * 2) * 16, Math.min(1, b.dt * 3)); },
    pat: [
      b => {
        every(b, 'fan', 1.5, () => { fan(b.x, b.y + 45, aimAt(b.x, b.y + 45), cnt(5), 0.2, 165, 1); b.mouthT = 0.35; });
        every(b, 'can', 1.0, () => {
          b.alt = !b.alt;
          const s = b.alt ? -1 : 1, n = cnt(3);
          for (let i = 0; i < n; i++) later(i * 0.1, () => { if (b.state !== 'fight') return; const cx = b.x + s * 56, cy = b.y + 64; shoot(cx, cy, aimAt(cx, cy), 230, 0); });
        });
      },
      b => {
        every(b, 'spout', 0.1, () => { shoot(b.x + rnd(-6, 6), b.y - 96, -PI / 2 + rnd(-0.95, 0.95), rnd(150, 225), 6, { ay: 165 }); b.steamT = 0.3; });
        every(b, 'shell', 2.4, () => { shoot(b.x, b.y + 45, aimAt(b.x, b.y + 45), 125, 2, { split: 1.1, sn: cnt(12), ss: 130, st: 0 }); b.mouthT = 0.4; });
      },
      b => {
