        every(b, 'needle', 1.8, () => { const cx = b.x, cy = b.y + 45, a = aimAt(cx, cy); for (let i = 0; i < cnt(6); i++) later(i * 0.07, () => { if (b.state === 'fight') shoot(cx, cy, a, 300, 3); }); b.mouthT = 0.5; });
        every(b, 'spout2', 0.24, () => { shoot(b.x, b.y - 96, -PI / 2 + rnd(-0.9, 0.9), rnd(160, 220), 6, { ay: 165 }); b.steamT = 0.3; });
      }
    ],
