      const ax = f1(clamp((PL.x - b.x) / 60, -4, 4)), ay = f1(clamp((PL.y - b.y) / 120, -1, 3));
      for (const pp of gx.pupils) pp.setAttribute('transform', 'translate(' + ax + ' ' + ay + ')');
      for (let i = 0; i < 2; i++) gx.cans[i].setAttribute('transform', 'rotate(' + f1(bossAim(b, i, i ? 56 : -56, 62)) + ')');
      b.steamT = Math.max(0, (b.steamT || 0) - b.dt);
      const st = b.steamT > 0;
      if (b.stV !== st) { b.stV = st; show(gx.steam, st); }
      if (st) gx.steam.setAttribute('transform', 'translate(0 -104) scale(' + (0.85 + Math.sin(t * 14) * 0.15).toFixed(2) + ')');
      if (b.phase === 2 && !b.raged) { b.raged = true; gx.body.setAttribute('fill', '#a45a74'); }
    } },
  { name: '陨石蝎王', en: 'METEOR SCORPION', hp: 1700, y0: 234, score: 40000, th: [0.66, 0.33], build: buildScorp,
    lines: ['尾巴要喷毒液了！', '陨石雨来了！'],
