        every(b, 'core', 2.1, () => { for (let i = 0; i < cnt(3); i++) later(i * 0.12, () => { if (b.state === 'fight') shoot(b.x, b.y + 64, aimAt(b.x, b.y + 64), 200, 1); }); });
