        every(b, 'snip', 0.55, () => { b.alt = !b.alt; const i = b.alt ? 0 : 1, s = i ? 1 : -1, cx = b.x + s * 100, cy = b.y + 104; shoot(cx, cy, aimAt(cx, cy), 220, 0); b['clawT' + i] = 0.2; });
      },
      b => {
