        every(b, 'spiral', 0.13, () => { b.a = (b.a || 0) + 0.37; const n = G.D.dens > 1.2 ? 3 : 2; for (let k = 0; k < n; k++) shoot(b.x, b.y + 50, b.a + (k * TAU) / n, 120, 4); });
