        gx.claws[i].bl.setAttribute('transform', 'rotate(' + a + ' 0 6)');
        gx.claws[i].br.setAttribute('transform', 'rotate(' + (-a) + ' 0 6)');
      }
    } },
  { name: '铁颚大帝', en: 'EMPEROR IRONJAW', hp: 2300, y0: 192, score: 80000, th: [0.7, 0.4, 0.15], build: buildIronjaw,
    lines: ['下巴张开了！小心弹幕帘！', '双重螺旋！看准缝隙！', '最后的疯狂！坚持住！'],
    hit(b, x, y, r) {
      const dx = (x - b.x) / (125 + r), dy = (y - b.y + 30) / (108 + r);
      if (dx * dx + dy * dy < 1) return true;
      if (Math.abs(x - b.x) < 100 + r && y > b.y && y < b.y + 112 + r) return true;
      for (const s of [-1, 1]) { const cx = b.x + s * 150, cy = b.y + 6; if ((x - cx) * (x - cx) + (y - cy) * (y - cy) < (40 + r) * (40 + r)) return true; }
      return false;
    },
    col(b, x, hw) { return Math.abs(x - b.x) < 185 + hw; },
    move(b) {
