              if (b.state !== 'fight') return;
              const n = cnt(10);
              for (let i = 0; i < n; i++) later(i * 0.045, () => { if (b.state === 'fight') shoot(b.x + s * 52, b.y - 3, a, 370, 3); });
            });
          }
          b.eyeT = 1.1;
        });
        every(b, 'sh', 1.3, () => {
          b.alt = !b.alt;
          const s = b.alt ? -1 : 1, a0 = aimAt(b.x + s * 158, b.y + 18);
          fan(b.x + s * 158 + Math.cos(a0) * 34, b.y + 18 + Math.sin(a0) * 34, a0, cnt(3), 0.18, 185, 1);
        });
      },
      b => {
        b.jawOpen = 1;
        every(b, 'cur', 0.075, () => { const w = Math.sin(b.pt * 2.1); shoot(b.x, b.y + 74, PI / 2 + w, 170, 5); shoot(b.x, b.y + 74, PI / 2 - w, 170, 5); });
        every(b, 'fr', 2.3, () => ring(b.x, b.y - 78, cnt(16), 115, 0, rnd(0, TAU)));
      },
      b => {
        b.jawOpen = 0.35;
        every(b, 'sp', 0.1, () => {
          b.a = (b.a || 0) + 0.2;
          for (let k = 0; k < 3; k++) { shoot(b.x, b.y + 20, b.a + (k * TAU) / 3, 120, 0); shoot(b.x, b.y + 20, -b.a + (k * TAU) / 3 + 0.5, 100, 3); }
        });
        every(b, 'sh', 1.9, () => { for (const s of [-1, 1]) { const a0 = aimAt(b.x + s * 158, b.y + 18); fan(b.x + s * 158 + Math.cos(a0) * 34, b.y + 18 + Math.sin(a0) * 34, a0, cnt(5), 0.16, 185, 1); } });
      },
      b => {
        b.jawOpen = 0.5 + 0.5 * Math.sin(b.pt * 8);
        every(b, 'fl', 0.62, () => { const n = cnt(22), o = rnd(0, TAU); ring(b.x, b.y + 40, n, 145, 5, o); ring(b.x, b.y + 40, n, 100, 0, o + PI / n); });
        every(b, 'nd', 1.3, () => { for (const s of [-1, 1]) { const ex = b.x + s * 52, ey = b.y - 3; fan(ex, ey, aimAt(ex, ey), cnt(3), 0.1, 320, 3); } });
      }
    ],
    anim(b) {
      const gx = b.gfx, t = b.t;
      b.jaw = lerp(b.jaw || 0, b.state === 'fight' ? b.jawOpen || 0 : 0.2, Math.min(1, b.dt * 6));
      gx.jaw.setAttribute('transform', 'translate(0 ' + f1(b.jaw * 34) + ')');
      b.eyeT = Math.max(0, (b.eyeT || 0) - b.dt);
      const eo = b.eyeT > 0 ? (Math.floor(t * 20) % 2 ? 1 : 0.35) : 1;
      if (b.eo !== eo) { b.eo = eo; gx.eyes.setAttribute('opacity', eo); }
      for (let i = 0; i < 2; i++) gx.shs[i].setAttribute('transform', 'rotate(' + f1(bossAim(b, i, i ? 158 : -158, 18)) + ')');
      const gem = Math.floor(t * 4) % 2 ? MAG : '#ff9ad0';
      if (b.gemC !== gem) { b.gemC = gem; gx.gem.setAttribute('fill', gem); }
    } }
];
function spawnBoss(i) {
  const d = BOSSES[i];
  const b = { d, x: 280, y: -200, hp: d.hp * G.D.hp, max: d.hp * G.D.hp, phase: 0, t: 0, pt: 0, dt: 0, state: 'enter', cd: {}, flash: 0, fcool: 0, trans: 0 };
  b.gfx = d.build(L.boss);
  b.g = b.gfx.g;
  b.hit = (x, y, r) => (b.state === 'fight' || b.state === 'enter') && d.hit(b, x, y, r);
  b.col = (x, hw) => b.state === 'fight' && d.col(b, x, hw);
  G.boss = b;
  SC.bbName.textContent = d.name;
  SC.bbEn.set(d.en);
  let td = '';
  for (const th of d.th) td += 'M' + f1(14 + 532 * th) + ' 10V30';
  SC.bbTicks.setAttribute('d', td);
  SC.bbFill.setAttribute('width', 0);
  show(SC.bb, true);
  b.g.setAttribute('transform', 'translate(280 -200)');
}
function updBoss(dt) {
  const b = G.boss;
  if (!b) return;
  b.dt = dt; b.t += dt; b.pt += dt;
  if (b.fcool > 0) b.fcool -= dt;
  if (b.state === 'enter') {
    b.y = lerp(-200, b.d.y0, easeOut(Math.min(1, b.t / 3)));
    if (b.t >= 3) { b.state = 'fight'; b.pt = 0; }
  } else if (b.state === 'fight') {
    b.d.move(b);
    if (b.trans > 0) b.trans -= dt; else b.d.pat[b.phase](b);
    if (b.phase < b.d.th.length && b.hp / b.max < b.d.th[b.phase]) {
      b.phase++; b.pt = 0; b.cd = {}; b.trans = 1.3;
      for (const x of EB) if (!x.dead) { x.dead = true; addScore(10); if (Math.random() < 0.3) spark(x.x, x.y, 1, 100, 2); }
      boom(b.x, b.y, 90, pick(['GRRR!', 'RAAAH!', 'KRAK!']), RED);
      shakeIt(10);
      AU.play('phase');
      pilotSay(b.phase === b.d.th.length ? 'worried' : 'shout', b.d.lines[b.phase - 1] || '小心！', 3);
    }
  } else if (b.state === 'dying') {
    b.dieT += dt;
    if (!b.gone) {
      b.x += rnd(-2, 2);
      b.dieBoom = (b.dieBoom || 0) - dt;
      if (b.dieBoom <= 0) {
        b.dieBoom = 0.11;
        boom(b.x + rnd(-120, 120), b.y + rnd(-80, 80), rnd(30, 64), Math.random() < 0.4 ? pick(WORDS.m) : null);
        shakeIt(6);
        AU.play('boom');
      }
      if (b.dieT > 2.6) {
        b.gone = true;
        boom(b.x, b.y, 230, 'KA-BOOM!!', RED);
        G.flash = 0.8;
        shakeIt(20);
        AU.play('huge');
        b.g.remove();
        show(SC.bb, false);
        later(2.6, stageClear);
      }
    }
  }
  if (!b.gone) {
    b.d.anim(b);
    b.g.setAttribute('transform', 'translate(' + f1(b.x) + ' ' + f1(b.y) + ')');
  }
  if (b.flash > 0) { b.flash -= dt; if (b.flash <= 0) b.g.classList.remove('flash'); }
  const shown = b.state === 'enter' ? Math.min(1, b.t / 2.5) : Math.max(0, b.hp / b.max);
  if (b.barShown !== shown) { b.barShown = shown; SC.bbFill.setAttribute('width', f1(532 * shown)); }
}
function hitBoss(b, dmg, cont) {
  if (b.state !== 'fight' || b.trans > 0) return;
  b.hp -= dmg;
  if (!cont) addScore(10);
  if (b.fcool <= 0) { b.g.classList.add('flash'); b.flash = 0.035; b.fcool = 0.3; if (!cont) AU.play('hit'); }
  if (b.hp <= 0) { b.hp = 0; bossDie(b); }
}
function bossDie(b) {
  b.state = 'dying'; b.dieT = 0;
  G.phase = 'bossDead';
  for (const x of EB) x.dead = true;
  for (const e of EN) if (!e.dead) killEnemy(e);
  addScore(b.d.score);
  pop('+' + b.d.score, b.x, b.y - 40, YEL, 24);
  MUS.stop();
  pilotSay('shout', '这下结束了！');
}

// ================================================================ flow: stages, results, screens
function showScreen(name) {
  show(SC.title, name === 'title');
  show(SC.help, name === 'help');
  show(SC.over, name === 'over');
  show(SC.end, name === 'end');
}
function clearWorld() {
  for (const e of EN) e.g.remove();
  for (const it of IT) it.g.remove();
  for (const f of FXS) f.g.remove();
  for (const p of POPS) p.c.g.remove();
  EN = []; EB = []; PS = []; IT = []; FXS = []; POPS = []; PARTS = []; TIMERS = []; GROUPS = {};
  if (G.boss) { G.boss.g.remove(); G.boss = null; }
  G.shake = 0; G.flash = 0; G.slow = 0; G.shook = false;
  L.shake.removeAttribute('transform');
  show(L.flash, false); show(L.laser, false); show(L.beam, false);
  show(SC.intro, false); show(SC.warn, false); show(SC.bb, false); show(SC.cut, false); show(SC.res, false); show(SC.pause, false);
  drawBullets(); drawShots(); drawParts();
}
function startGame() {
  G.D = DIFFS[G.diff];
  G.score = 0; G.lives = 3; G.bombs = G.D.bombs; G.power = 1; G.shield = false; G.energy = 0;
  G.grazeAll = 0; G.killsAll = 0; G.hi0 = HI[G.diff] || 0;
  L.hitDot.setAttribute('r', f1(G.D.hitR + 1.3));
  showScreen(null);
  startStage(0);
}
function startStage(i) {
  clearWorld();
  G.stage = i; G.mode = 'play'; G.phase = 'intro'; G.pt = 0; G.st = 0; G.si = 0; G.scriptDone = false; G.endT = 0;
  G.scroll = 0; G.scrollSpd = STAGES[i].scroll;
  G.stats = { spawned: 0, killed: 0, graze: 0, hits: 0 };
  G.wantBomb = G.wantSpecial = false;
  buildBackground(i);
  Object.assign(PL, { alive: true, x: 280, y: 790, enterT: 1.0, inv: 2.0, respInv: 0, bombT: 0, specT: 0, fireT: 0, laser: false, bank: 0 });
  const s = STAGES[i];
  SC.introCap.textContent = s.cap;
  SC.introNo.textContent = '第 ' + (i + 1) + ' 话';
  SC.introName.textContent = s.name;
  SC.introEn.set(s.en);
  SC.introSub.textContent = s.sub;
  SC.introIn.setAttribute('transform', 'translate(-620 0)');
  show(SC.intro, true);
  MUS.play(s.music);
  pilotSay('normal', s.line, 3);
}
function startWarning() {
  G.phase = 'warning'; G.pt = 0;
  SC.wBoss.textContent = '';
  const d = BOSSES[STAGES[G.stage].boss];
  d.build(SC.wBoss);
  SC.wName.textContent = d.name;
  SC.wNameEn.set(d.en);
  animWarn(0);
  show(SC.warn, true);
  MUS.stop();
  AU.play('warn');
  pilotSay('shout', '来吧，大家伙！', 3.6);
}
function animWarn(t) {
  const slide = (t0, dir) => { const k = clamp((t - t0) / 0.35, 0, 1), out = clamp((t - 3.4) / 0.4, 0, 1); return f1(dir * 620 * (1 - easeOut(k)) - dir * 620 * easeIn(out)); };
  SC.wA.setAttribute('transform', 'translate(' + slide(0, -1) + ' 0)');
  SC.wB.setAttribute('transform', 'translate(' + slide(0.3, 1) + ' 0)');
  SC.wC.setAttribute('transform', 'translate(' + slide(0.6, -1) + ' 0)');
  SC.wText.g.setAttribute('opacity', Math.floor(t * 5) % 2 ? 0.62 : 1);
  if (t < 3.4) shakeIt(1.5);
}
function animCut(dt) {
  G.cutT += dt;
  const t = G.cutT;
  const x = t < 0.15 ? 620 * (1 - t / 0.15) : t > 0.7 ? -620 * easeIn(Math.min(1, (t - 0.7) / 0.2)) : 0;
  SC.cut.setAttribute('transform', 'translate(' + f1(x) + ' 0)');
  if (t > 0.9) show(SC.cut, false);
}
function stageClear() {
  if (G.mode !== 'play') return;
  if (G.lives <= 0) { gameOver(); return; }
  G.mode = 'result'; G.resT = 0; G.lock = 0.8;
  const st = G.stats;
  const rate = st.spawned ? st.killed / st.spawned : 1;
  const kb = Math.floor(rate * 100) * 300, gb = st.graze * 100, nb = st.hits === 0 ? 50000 * (G.stage + 1) : 0;
  G.res = { rate, kb, gb, nb, total: kb + gb + nb };
  addScore(G.res.total);
  saveHi();
  SC.resTitle.set(G.stage === 2 ? 'FINAL CLEAR!' : 'STAGE CLEAR!');
  SC.resSub.textContent = '第 ' + (G.stage + 1) + ' 话 · ' + STAGES[G.stage].name + '　完！';
  SC.resRows[0].v.textContent = Math.round(rate * 100) + '%';
  SC.resRows[0].b.set('+' + kb);
  SC.resRows[1].v.textContent = String(st.graze);
  SC.resRows[1].b.set('+' + gb);
  SC.resRows[2].v.textContent = nb ? '达成！' : '未达成';
  SC.resRows[2].v.setAttribute('fill', nb ? '#1a9a4a' : '#888');
  SC.resRows[2].b.set('+' + nb);
  SC.resTotal.set('+' + G.res.total);
  SC.resScore.set(String(G.score).padStart(8, '0'));
  SC.resHint.textContent = G.stage === 2 ? '按 Enter / Z 查看结局' : '按 Enter / Z 进入下一话';
  for (const r of SC.resRows) show(r.rg, false);
  show(SC.resTotalG, false); show(SC.resScoreG, false); show(SC.resHint, false);
  show(SC.res, true);
  MUS.play('win');
  pilotSay('happy', G.stage === 2 ? '我们赢了！' : '搞定！下一站！', 4);
}
function updResult(dt) {
  G.resT += dt;
  const t = G.resT;
  SC.resRows.forEach((r, i) => { if (t > 0.5 + i * 0.45 && r.rg.style.display === 'none') { show(r.rg, true); AU.play('ding'); } });
  if (t > 2 && SC.resTotalG.style.display === 'none') { show(SC.resTotalG, true); show(SC.resScoreG, true); AU.play('item'); }
  if (t > 2.4) show(SC.resHint, Math.floor(t * 2.5) % 2 === 0);
  G.scroll += G.scrollSpd * dt;
  updBG(G.scroll);
  updPlayer(dt);
  updItems(dt);
  updFx(dt); updParts(dt); updPops(dt);
}
function resultNext() {
  if (G.resT < 2.4) { G.resT = 2.4; return; }
  AU.play('select');
  show(SC.res, false);
  if (G.stage < 2) startStage(G.stage + 1); else showEnding();
}
function gameOver() {
  if (G.mode !== 'play' && G.mode !== 'pause') return;
  G.mode = 'over'; G.lock = 1;
  saveHi();
  SC.oScore.set(String(G.score).padStart(8, '0'));
  SC.oHi.set(String(HI[G.diff] || 0).padStart(8, '0'));
  show(SC.oNew, G.score > G.hi0);
  SC.oReach.textContent = '到达：第 ' + (G.stage + 1) + ' 话 · ' + STAGES[G.stage].name + '　难度：' + G.D.name;
  SC.oMenu.sel = 0; SC.oMenu.refresh();
  clearWorld();
  showScreen('over');
  MUS.play('over');
}
function showEnding() {
  G.mode = 'end'; G.lock = 1;
  saveHi();
  SC.eScore.set(String(G.score).padStart(8, '0'));
  SC.eHi.set(String(HI[G.diff] || 0).padStart(8, '0'));
  show(SC.eNew, G.score > G.hi0);
  SC.eStats.textContent = '总击坠 ' + G.killsAll + '　总擦弹 ' + G.grazeAll + '　难度：' + G.D.name;
  SC.eMenu.sel = 0; SC.eMenu.refresh();
  clearWorld();
  showScreen('end');
  MUS.play('end');
}
function toTitle() {
  saveHi();
  clearWorld();
  G.mode = 'title';
  refreshTitle();
  showScreen('title');
  MUS.play('title');
}
function overPick(i) {
  if (G.lock > 0 || (G.mode !== 'over' && G.mode !== 'end')) return;
  AU.play('select');
  if (i === 0) startGame(); else toTitle();
}
function pauseGame() {
  if (G.mode !== 'play') return;
  G.mode = 'pause';
  if (G.boss) { G.boss.flash = 0; G.boss.g.classList.remove('flash'); }
  for (const e of EN) { e.flash = 0; e.g.classList.remove('flash'); }
  SC.pMenu.sel = 0; SC.pMenu.refresh();
  show(SC.pause, true);
}
function resumeGame() { G.mode = 'play'; show(SC.pause, false); }
function pausePick(i) {
  if (G.mode !== 'pause') return;
  AU.play('select');
  if (i === 0) resumeGame();
  else if (i === 1) startGame();
  else toTitle();
}
function openHelp(from) { G.helpFrom = from; G.mode = 'help'; showScreen('help'); AU.play('select'); }
function closeHelp() {
  AU.play('back');
  if (G.helpFrom === 'pause') { G.mode = 'pause'; showScreen(null); show(SC.pause, true); }
  else { G.mode = 'title'; showScreen('title'); }
}
function cycleDiff(d) { G.diff = DIFF_KEYS[(DIFF_KEYS.indexOf(G.diff) + d + 3) % 3]; refreshTitle(); AU.play('move'); }
function titlePick(i) {
  if (G.mode !== 'title') return;
  if (i === 0) cycleDiff(1);
  else if (i === 1) { AU.play('select'); startGame(); }
  else openHelp('title');
}

// ================================================================ rendering
function drawBullets() {
  const ds = BT.map(() => ''), hs = BT.map(() => '');
  for (const b of EB) {
    const t = b.type, bt = BT[t];
    if (bt.needle) {
      const sp = Math.hypot(b.vx, b.vy) || 1, ux = b.vx / sp, uy = b.vy / sp, w = bt.r, l = 9;
      ds[t] += 'M' + f1(b.x + ux * l) + ' ' + f1(b.y + uy * l) + 'L' + f1(b.x - uy * w) + ' ' + f1(b.y + ux * w) + 'L' + f1(b.x - ux * l) + ' ' + f1(b.y - uy * l) + 'L' + f1(b.x + uy * w) + ' ' + f1(b.y - ux * w) + 'Z';
      hs[t] += circD(b.x + ux * 2, b.y + uy * 2, 1.6);
    } else {
      ds[t] += circD(b.x, b.y, bt.r);
      hs[t] += circD(b.x - bt.r * 0.3, b.y - bt.r * 0.3, f1(bt.r * 0.34));
    }
  }
  for (let t = 0; t < BT.length; t++) {
    const q = L.eb[t];
    if (ds[t] || !q.empty) { q.main.setAttribute('d', ds[t]); q.hl.setAttribute('d', hs[t]); q.empty = !ds[t]; }
  }
}
function drawShots() {
  let dv = '', dsp = '', dm = '';
  for (const s of PS) {
    if (s.k === 'v') dv += 'M' + f1(s.x - 3) + ' ' + f1(s.y - 11) + 'h6v22h-6Z';
    else if (s.k === 's') dsp += 'M' + f1(s.x) + ' ' + f1(s.y - 9) + 'l5 9l-5 9l-5 -9Z';
    else dm += circD(s.x, s.y, 5);
  }
  const set = (n, d) => { if (n._d !== d) { n._d = d; n.setAttribute('d', d); } };
  set(L.ps.v, dv); set(L.ps.s, dsp); set(L.ps.m, dm);
}
function drawParts() {
  let dy = '', dc = '';
  for (const p of PARTS) {
    const seg = 'M' + f1(p.x) + ' ' + f1(p.y) + 'L' + f1(p.x - p.vx * 0.045) + ' ' + f1(p.y - p.vy * 0.045);
    if (p.c === 2) dc += seg; else dy += seg;
  }
  const set = (n, d) => { if (n._d !== d) { n._d = d; n.setAttribute('d', d); } };
  set(L.pInk, dy + dc); set(L.pYel, dy); set(L.pCy, dc);
}
function drawPlayer() {
  const p = PL;
  const vis = p.alive && !(p.respInv > 0 && Math.floor(G.rt * 15) % 2 === 0);
  if (L.pgVis !== vis) { L.pgVis = vis; show(L.pg, vis); }
  if (!p.alive) return;
  L.pg.setAttribute('transform', 'translate(' + f1(p.x) + ' ' + f1(p.y) + ')');
  L.ship.body.setAttribute('transform', 'scale(' + (1 - Math.abs(p.bank) * 0.22).toFixed(3) + ' 1)');
  L.ship.flame.setAttribute('transform', 'translate(0 22) scale(1 ' + (0.7 + Math.random() * 0.55).toFixed(2) + ') translate(0 -22)');
  if (L.fVis !== p.focus) { L.fVis = p.focus; show(L.focusG, p.focus); }
  if (p.focus) L.focusRing.setAttribute('transform', 'rotate(' + f1((G.rt * 180) % 360) + ')');
  if (L.sVis !== G.shield) { L.sVis = G.shield; show(L.shieldG, G.shield); }
  if (G.shield) L.shieldRing.setAttribute('transform', 'rotate(' + f1((-G.rt * 120) % 360) + ')');
}
function drawLaser() {
  const p = PL, on = p.laser && p.alive && p.enterT <= 0;
  if (L.lzVis !== on) { L.lzVis = on; show(L.laser, on); }
  if (!on) return;
  const w = 23 + Math.sin(G.rt * 40) * 3, h = p.y - 22;
  sa(L.laserO, { x: f1(p.x - w / 2), y: -10, width: f1(w), height: f1(h) });
  sa(L.laserI, { x: f1(p.x - w * 0.18), y: -10, width: f1(w * 0.36), height: f1(h) });
}
function drawBeam() {
  const p = PL, on = p.alive && p.specT > 0 && p.specT < 2.6;
  if (L.bmVis !== on) { L.bmVis = on; show(L.beam, on); }
  if (!on) return;
  const k = Math.min(1, (2.6 - p.specT) / 0.2) * Math.min(1, p.specT / 0.3);
  const hw = 62 * k, top = -20, bot = p.y - 26, steps = 12;
  let dO = 'M' + f1(p.x - hw * 0.4) + ' ' + f1(bot);
  for (let i = 0; i <= steps; i++) dO += 'L' + f1(p.x - hw + rnd(-6, 6) * k) + ' ' + f1(bot + ((top - bot) * i) / steps);
  for (let i = steps; i >= 0; i--) dO += 'L' + f1(p.x + hw + rnd(-6, 6) * k) + ' ' + f1(bot + ((top - bot) * i) / steps);
  dO += 'L' + f1(p.x + hw * 0.4) + ' ' + f1(bot) + 'Z';
  const iw = hw * 0.45;
  const dI = 'M' + f1(p.x - iw) + ' ' + top + 'L' + f1(p.x + iw) + ' ' + top + 'L' + f1(p.x + iw * 0.35) + ' ' + f1(bot) + 'L' + f1(p.x - iw * 0.35) + ' ' + f1(bot) + 'Z';
  let dl = '';
  for (let i = 0; i < 7; i++) dl += 'M' + f1(p.x + rnd(-hw * 0.85, hw * 0.85)) + ' ' + f1(rnd(0, bot)) + 'v' + f1(-rnd(30, 80));
  L.beamO.setAttribute('d', dO);
  L.beamI.setAttribute('d', dI);
  L.beamL.setAttribute('d', dl);
}
function render(dt) {
  for (const e of EN) placeEnemy(e);
  for (const it of IT) it.g.setAttribute('transform', 'translate(' + f1(it.x) + ' ' + f1(it.y) + ') scale(' + (1 + Math.sin(it.t * 9) * 0.08).toFixed(3) + ')');
  drawPlayer(); drawLaser(); drawBeam(); drawShots(); drawBullets(); drawParts();
  if (G.shake > 0.3) {
    G.shake = Math.max(0, G.shake - dt * 30);
    L.shake.setAttribute('transform', 'translate(' + f1(rnd(-G.shake, G.shake)) + ' ' + f1(rnd(-G.shake, G.shake)) + ')');
    G.shook = true;
  } else if (G.shook) { G.shook = false; G.shake = 0; L.shake.removeAttribute('transform'); }
  if (G.flash > 0) {
    G.flash -= dt;
    show(L.flash, true);
    L.flash.setAttribute('opacity', clamp(G.flash * 1.8, 0, 0.9).toFixed(2));
  } else if (L.flash.style.display !== 'none') show(L.flash, false);
}

// ================================================================ update loop
function updPlay(dt) {
  G.pt += dt;
  let wdt = dt;
  if (G.slow > 0) { G.slow -= dt; wdt = dt * 0.25; }
  G.scroll += G.scrollSpd * wdt;
  updBG(G.scroll);
  updTimers(wdt);
  if (G.mode !== 'play') return;
  if (G.phase === 'intro') {
    const t = G.pt, x = t < 0.45 ? -620 * (1 - easeOut(t / 0.45)) : t > 2.5 ? 620 * easeIn(Math.min(1, (t - 2.5) / 0.4)) : 0;
    SC.introIn.setAttribute('transform', 'translate(' + f1(x) + ' 0)');
    if (t > 2.9) { show(SC.intro, false); G.phase = 'waves'; G.pt = 0; }
  } else if (G.phase === 'waves') {
    G.st += wdt;
    const sc = STAGES[G.stage].script;
    while (G.si < sc.length && sc[G.si][0] <= G.st) { const ev = sc[G.si++]; WAVES[ev[1]](ev[2] || {}); }
    if (G.scriptDone) {
      G.endT += wdt;
      if (G.endT > 1.5 && (!EN.some(e => !e.dead && !e.T.nc) || G.endT > 9)) startWarning();
    }
  } else if (G.phase === 'warning') {
    animWarn(G.pt);
    if (G.pt > 3.9) { show(SC.warn, false); spawnBoss(STAGES[G.stage].boss); G.phase = 'boss'; G.pt = 0; MUS.play('boss'); }
  }
  updPlayer(dt);
  updEnemies(wdt);
  updBoss(wdt);
  updBullets(wdt);
  updShots(dt);
  updCollide();
  updItems(wdt);
  updFx(dt); updParts(dt); updPops(dt);
  if (SC.cut.style.display !== 'none') animCut(dt);
}
function updTitle() {
  SC.rays.setAttribute('transform', 'translate(900 420) rotate(' + f1((G.rt * 5) % 360) + ')');
  SC.tShip.setAttribute('transform', 'translate(880 ' + f1(450 + Math.sin(G.rt * 2) * 8) + ') rotate(24) scale(4.1)');
}
let lastT = 0;
function frame(now) {
  requestAnimationFrame(frame);
  if (!lastT) lastT = now;
  let dt = (now - lastT) / 1000;
  lastT = now;
  if (dt > 0.05) dt = 0.05;
  if (dt < 0) dt = 0;
  G.rt += dt;
  if (G.lock > 0) G.lock -= dt;
  if (G.mode === 'play') updPlay(dt);
  else if (G.mode === 'result') updResult(dt);
  else if (G.mode === 'title') updTitle();
  else if (G.mode === 'end') SC.endRays.setAttribute('transform', 'translate(640 420) rotate(' + f1((G.rt * 6) % 360) + ')');
  updPilot(dt);
  if (G.mode === 'play' || G.mode === 'result') render(dt);
  updHUD();
}

// ================================================================ input
const KEYMAP = {
  ArrowUp: 'up', KeyW: 'up', ArrowDown: 'down', KeyS: 'down', ArrowLeft: 'left', KeyA: 'left', ArrowRight: 'right', KeyD: 'right',
  KeyZ: 'fire', Space: 'fire', KeyJ: 'fire', KeyX: 'bomb', KeyK: 'bomb', KeyC: 'special', KeyL: 'special',
  ShiftLeft: 'focus', ShiftRight: 'focus', KeyP: 'pause', Escape: 'esc', KeyH: 'help', KeyM: 'mute', Enter: 'enter', NumpadEnter: 'enter'
};
const KEYMAP2 = {
  z: 'fire', ' ': 'fire', x: 'bomb', c: 'special', p: 'pause', h: 'help', m: 'mute', w: 'up', a: 'left', s: 'down', d: 'right',
  shift: 'focus', enter: 'enter', escape: 'esc', arrowup: 'up', arrowdown: 'down', arrowleft: 'left', arrowright: 'right'
};
const K = {}, KC = {}, DOWN = new Set();
function actOf(e) { return KEYMAP[e.code] || KEYMAP2[(e.key || '').toLowerCase()]; }
function onAction(a) {
  if (a === 'mute') { AU.setMute(!AU.muted); return; }
  const m = G.mode;
  if (m === 'title') {
    if (a === 'left') cycleDiff(-1);
    else if (a === 'right') cycleDiff(1);
    else if (a === 'help') openHelp('title');
    else menuKey(SC.tMenu, a, titlePick);
  } else if (m === 'help') {
    if (a === 'enter' || a === 'esc' || a === 'help' || a === 'bomb' || a === 'fire') closeHelp();
  } else if (m === 'play') {
    if (a === 'pause' || a === 'esc') { pauseGame(); AU.play('select'); }
    else if (a === 'help') { pauseGame(); openHelp('pause'); }
    else if (a === 'bomb') G.wantBomb = true;
    else if (a === 'special') G.wantSpecial = true;
  } else if (m === 'pause') {
    if (a === 'pause' || a === 'esc') { resumeGame(); AU.play('back'); }
    else if (a === 'help') openHelp('pause');
    else menuKey(SC.pMenu, a, pausePick);
  } else if (m === 'result') {
    if ((a === 'enter' || a === 'fire') && G.lock <= 0) resultNext();
  } else if (m === 'over' || m === 'end') {
    if (G.lock <= 0) menuKey(m === 'over' ? SC.oMenu : SC.eMenu, a, overPick);
  }
}
window.addEventListener('keydown', e => {
  AU.init();
  const a = actOf(e);
  if (!a) return;
  e.preventDefault();
  const id = e.code || e.key;
  if (DOWN.has(id)) {
    if (e.repeat && (a === 'up' || a === 'down') && G.mode !== 'play') onAction(a);
    return;
  }
  DOWN.add(id);
  KC[a] = (KC[a] || 0) + 1;
  K[a] = true;
  onAction(a);
});
window.addEventListener('keyup', e => {
  const a = actOf(e), id = e.code || e.key;
  if (!a || !DOWN.has(id)) return;
  DOWN.delete(id);
  KC[a] = Math.max(0, (KC[a] || 0) - 1);
  K[a] = KC[a] > 0;
});
window.addEventListener('blur', () => {
  DOWN.clear();
  for (const k in K) { K[k] = false; KC[k] = 0; }
  if (G.mode === 'play') pauseGame();
});
window.addEventListener('pointerdown', () => AU.init());

// test hooks for automated play-testing
window.__csf = {
  G, PL,
  get enemies() { return EN.length; },
  get bullets() { return EB.length; },
  get audio() { return AU.ctx ? AU.ctx.state : 'none'; },
  stage(n) { if (G.mode !== 'play') startGame(); startStage(n); return 'ok'; },
  skipToBoss() {
    if (G.mode !== 'play') return 'not playing';
    for (const e of EN) e.g.remove();
    EN = []; TIMERS = [];
    G.si = STAGES[G.stage].script.length; G.scriptDone = true; G.phase = 'waves'; G.endT = 99;
    show(SC.intro, false);
    return 'ok';
  },
  fill() { G.energy = 100; return 'ok'; },
  god(v) { G.god = v !== false; return G.god; },
  power(n) { G.power = clamp(n, 1, 4); return G.power; },
  hurtBoss(f) { if (!G.boss) return false; G.boss.hp = G.boss.max * f; return true; }
};

// ================================================================ boot
buildScene();
buildHUD();
buildPlayer();
buildTitle();
buildHelp();
buildOver();
buildEnd();
buildIntro();
buildWarn();
buildCut();
buildBossBar();
buildPause();
buildResult();
buildBackground(0);
refreshTitle();
showScreen('title');
MUS.play('title');
updHUD();
requestAnimationFrame(frame);
})();
